window.CURRILOOP_EDU_DATA={"version":"education-text-v25-psych-pages1-5-source-gap-recovery","topics":[{"id":"edu-001","area":"교육심리","title":"피아제의 인지발달","page":1,"summary":"도식과 인지적 평형화, 동화·조절을 중심으로 이해한다.","sections":[{"heading":"핵심 개념","text":"도식은 사고의 틀이며, 동화는 기존 도식으로 새 경험을 이해하는 과정, 조절은 기존 도식을 수정하는 과정이다."},{"heading":"학습 포인트","text":"원문은 동화·조절을 통한 평형화와 발달의 관계를 정리한다."}],"questions":[{"id":"edu-001-q1","prompt":"동화와 조절을 구분하여 서술하시오.","answer":"동화는 기존의 도식에 새로운 경험을 통합하는 것이고, 조절은 새로운 경험에 맞추어 기존 도식을 바꾸는 것이다.","keywords":["동화","기존 도식","조절","수정"],"kind":"비교"},{"id":"edu-001-q2","prompt":"인지적 평형화와 동화·조절의 관계를 설명하시오.","answer":"새로운 경험으로 생기는 인지적 불균형을 동화와 조절을 통해 조정하며 평형화를 추구한다.","keywords":["불균형","동화","조절","평형화"],"kind":"설명"}],"source":{"document":"교육학_261019_163033.pdf","page":1,"status":"필기 원문 참조·핵심 개념 수동 요약","note":"요약·문제는 제작 편집이며 원문 직인용이나 공식 답안이 아닙니다."}},{"id":"edu-002","area":"교육심리","title":"에릭슨의 심리사회적 발달","page":1,"summary":"청소년기의 정체감 형성과 역할 혼미의 갈등, 교사의 지원을 살핀다.","sections":[{"heading":"청소년기 발달과업","text":"자아정체감 대 역할혼미의 위기를 경험한다."},{"heading":"지도 방향","text":"다양한 역할 경험, 진로 탐색, 자기 성찰 및 긍정적 피드백을 지원한다."}],"questions":[{"id":"edu-002-q1","prompt":"에릭슨 이론에서 청소년기의 주요 발달과업을 설명하시오.","answer":"자아정체감을 형성하는 것이 주요 과업이며, 역할 혼미와의 갈등을 해결해 나간다.","keywords":["자아정체감","역할 혼미"],"kind":"개념"},{"id":"edu-002-q2","prompt":"정체감 형성을 돕는 교사의 지원 방안을 두 가지 제시하시오.","answer":"① 다양한 역할과 진로를 탐색할 수 있는 기회를 제공한다. ② 학생이 자신의 경험과 가치관을 성찰하도록 돕고 구체적이고 지지적인 피드백을 제공한다.","keywords":["역할·진로 탐색 기회","자기성찰 지원·피드백"],"kind":"적용"}],"source":{"document":"교육학_261019_163033.pdf","page":1,"status":"필기 원문 참조·핵심 개념 수동 요약","note":"요약·문제는 제작 편집이며 원문 직인용이나 공식 답안이 아닙니다."}},{"id":"edu-003","area":"교육심리","title":"비고츠키의 근접발달영역","page":1,"summary":"현재 발달 수준과 잠재적 발달 수준의 차이 및 비계 설정을 이해한다.","sections":[{"heading":"근접발달영역(ZPD)","text":"학습자가 혼자 수행할 수 있는 실제 발달 수준과 적절한 도움을 받아 수행할 수 있는 잠재적 발달 수준 사이의 차이."},{"heading":"교수 지원","text":"단서·질문·모델링 등의 비계를 제공하고 학습자의 수행 능력에 따라 지원을 조절한다."}],"questions":[{"id":"edu-003-q1","prompt":"근접발달영역(ZPD)을 정의하시오.","answer":"혼자 수행할 수 있는 실제 발달 수준과 도움을 받아 수행할 수 있는 잠재적 발달 수준 사이의 영역이다.","keywords":["실제 발달 수준","잠재적 발달 수준","도움"],"kind":"개념"},{"id":"edu-003-q2","prompt":"비계 설정을 활용한 교사의 지원 방안을 서술하시오.","answer":"도움으로 해결 가능한 과제를 선정하고, 단서·모델링·질문을 제공하며 숙달에 따라 도움을 점차 줄인다.","keywords":["적절한 과제","비계","점진적 감소"],"kind":"적용"}],"source":{"document":"교육학_261019_163033.pdf","page":1,"status":"필기 원문 참조·핵심 개념 수동 요약","note":"요약·문제는 제작 편집이며 원문 직인용이나 공식 답안이 아닙니다."}},{"id":"edu-004","area":"학습이론","title":"스키너의 조작적 조건형성","page":2,"summary":"강화와 벌, 강화계획 및 행동 수정의 기초를 학습한다.","sections":[{"heading":"행동주의적 관점","text":"행동의 결과에 따라 행동의 발생 가능성이 변화한다."},{"heading":"강화와 벌","text":"강화는 행동의 발생 가능성을 높이고 벌은 낮춘다. 정적(+)은 자극의 제시, 부적(-)은 자극의 제거를 가리키며, 좋은 행동·나쁜 행동을 뜻하는 구분이 아니다. 따라서 정적 강화·부적 강화·정적 벌·부적 벌을 행동의 변화 방향과 자극 조작을 함께 기준으로 구별한다."},{"heading":"강화계획","text":"시간 간격과 반응 횟수, 고정과 변동을 기준으로 구분한다."}],"questions":[{"id":"edu-004-q1","prompt":"정적 강화와 부적 강화를 비교하시오.","answer":"정적 강화는 행동 뒤에 선호 자극을 제시하여 그 행동의 발생 가능성을 높이는 것이다. 부적 강화는 행동 뒤에 혐오 자극이 제거되거나 회피되게 하여 그 행동의 발생 가능성을 높이는 것이다. 두 경우 모두 핵심은 행동의 증가이며, 정적·부적은 자극 조작의 차이다.","keywords":["행동 발생 가능성 증가(공통)","정적 강화: 선호 자극 제시","부적 강화: 혐오 자극 제거·회피"],"kind":"비교"},{"id":"edu-004-q2","prompt":"부적 강화와 벌을 구별하시오.","answer":"부적 강화는 혐오 자극의 제거 또는 회피가 뒤따라 특정 행동의 발생 가능성을 높이는 절차다. 벌은 자극의 제시 또는 제거를 통해 특정 행동의 발생 가능성을 낮추는 절차다. ‘부적’이라는 말이 곧 벌을 의미하지 않는다.","keywords":["부적 강화: 행동 증가","벌: 행동 감소","정적·부적은 자극의 제시·제거를 뜻함"],"kind":"비교"}],"source":{"document":"교육학_261019_163033.pdf","page":2,"status":"필기 원문 참조·핵심 개념 수동 요약","note":"요약·문제는 제작 편집이며 원문 직인용이나 공식 답안이 아닙니다."}},{"id":"edu-005","area":"학습이론","title":"자기조절학습","page":2,"summary":"학습자가 계획·수행 중 점검과 조절·자기반성을 순환적으로 연결해 학습을 관리하는 과정을 이해한다.","sections":[{"heading":"핵심 개념","text":"학습자가 자신의 목표·전략·수행 과정을 점검하고 조정하는 학습."},{"heading":"주요 과정","text":"계획, 수행 중 점검과 조절, 결과 평가와 반성."}],"questions":[{"id":"edu-005-q1","prompt":"자기조절학습에서 학습자가 수행하는 대표적인 순환적 과정을 설명하시오.","answer":"학습자는 목표와 전략을 계획하고, 수행 중 자신의 학습 과정을 점검·조절하며, 결과를 평가·반성하여 다음 학습의 목표와 전략에 반영한다. 이 과정은 순환적으로 조정될 수 있다.","keywords":["계획","점검","조절","평가"],"kind":"절차"}],"source":{"document":"교육학_261019_163033.pdf","page":2,"status":"필기 원문 참조·핵심 개념 수동 요약","note":"요약·문제는 제작 편집이며 원문 직인용이나 공식 답안이 아닙니다."}},{"id":"edu-006","area":"교육과정","title":"타일러의 교육과정 개발 모형","page":6,"summary":"교육목표·학습경험 선정·조직·평가의 연계를 살핀다.","sections":[{"heading":"개발 과정","text":"교육목표 설정 → 학습경험 선정 → 학습경험 조직 → 학습경험 평가."},{"heading":"목표 설정","text":"학습자 특성, 현대 사회의 요구, 교과 전문가 견해를 검토하고 교육철학·학습심리학을 고려한다."},{"heading":"학습경험 조직","text":"계속성, 계열성, 통합성에 주목한다."}],"questions":[{"id":"edu-006-q1","prompt":"타일러 모형의 교육과정 개발 과정을 서술하시오.","answer":"교육목표 설정 → 학습경험 선정 → 학습경험 조직 → 평가의 순서로 진행된다.","keywords":["목표 설정","경험 선정","경험 조직","평가"],"kind":"절차"},{"id":"edu-006-q2","prompt":"타일러 모형에서 학습경험 조직의 원리 세 가지는?","answer":"계속성, 계열성, 통합성이다.","keywords":["계속성","계열성","통합성"],"kind":"개념"},{"id":"edu-006-q3","prompt":"타일러 모형에서 교육목표 후보를 선정한 뒤 최종 목표로 좁히는 과정을 설명하시오.","answer":"학습자 연구·현대 사회의 요구·교과 전문가의 견해에서 잠정적인 교육목표를 도출하고, 교육철학과 학습심리학이라는 두 여과 장치를 통해 목표를 선정한다.","keywords":["세 원천에서 잠정 목표 도출","교육철학","학습심리학"],"kind":"개념"}],"source":{"document":"교육학_261019_163033.pdf","page":6,"status":"필기 원문 참조·핵심 개념 수동 요약","note":"요약·문제는 제작 편집이며 원문 직인용이나 공식 답안이 아닙니다."}},{"id":"edu-007","area":"교육과정","title":"타바의 교육과정 개발 모형","page":6,"summary":"교사 중심의 귀납적 개발 관점을 이해한다.","sections":[{"heading":"핵심 특징","text":"교사의 교육과정 개발 참여, 단원에서 출발하는 귀납적 접근."},{"heading":"절차의 특징","text":"학습자의 요구 진단을 토대로 목표·내용·경험을 선정하고 조직한다."}],"questions":[{"id":"edu-007-q1","prompt":"타바 모형이 타일러 모형과 구별되는 핵심 특징을 서술하시오.","answer":"교사의 참여를 중시하고 구체적인 단원 개발에서 출발하여 교육과정을 구성하는 귀납적 접근이다.","keywords":["교사 참여","단원 개발","귀납적"],"kind":"비교"}],"source":{"document":"교육학_261019_163033.pdf","page":6,"status":"필기 원문 참조·핵심 개념 수동 요약","note":"요약·문제는 제작 편집이며 원문 직인용이나 공식 답안이 아닙니다."}},{"id":"edu-008","area":"교육과정","title":"위긴스·맥타이의 역행설계","page":6,"summary":"바라는 결과, 수용 가능한 증거, 학습경험 및 수업 계획의 순서를 이해한다.","sections":[{"heading":"세 단계","text":"바라는 결과의 확인 → 수용 가능한 증거의 결정 → 학습경험과 수업의 계획."},{"heading":"핵심 취지","text":"교육목표에 부합하는 평가 증거를 먼저 설계한 뒤 학습 경험을 조직한다."}],"questions":[{"id":"edu-008-q1","prompt":"역행설계의 세 단계를 순서대로 설명하시오.","answer":"바라는 결과의 확인 → 수용 가능한 증거의 결정 → 학습경험과 수업의 계획이다.","keywords":["바라는 결과","수용 가능한 증거","학습경험 계획"],"kind":"절차"},{"id":"edu-008-q2","prompt":"역행설계에서 평가 증거를 학습활동보다 먼저 고려하는 이유는?","answer":"도달해야 할 이해와 수행을 명확히 하고 이에 맞는 학습경험을 역으로 설계하기 위해서다.","keywords":["평가 증거","학습경험","목표 정렬"],"kind":"설명"}],"source":{"document":"교육학_261019_163033.pdf","page":6,"status":"필기 원문 참조·핵심 개념 수동 요약","note":"요약·문제는 제작 편집이며 원문 직인용이나 공식 답안이 아닙니다."}},{"id":"edu-009","area":"교육과정","title":"워커의 자연주의 모형","page":6,"summary":"강령·숙의·설계로 이어지는 실제적 개발 과정을 학습한다.","sections":[{"heading":"핵심 단계","text":"강령(참여자들의 신념·가치·입장) → 숙의(대안에 대한 논의) → 설계(교육과정 구성)."},{"heading":"특징","text":"실제 교육과정 개발 과정의 협의와 가치 조정을 설명한다."}],"questions":[{"id":"edu-009-q1","prompt":"워커의 자연주의 모형에서 강령·숙의·설계 단계별로 수행하는 활동을 설명하시오.","answer":"강령 단계에서는 참여자의 신념·가치·입장을 제시한다. 숙의 단계에서는 대안을 검토하고 견해를 협의·조정한다. 설계 단계에서는 합의된 방향을 구체적인 교육과정으로 구성한다.","keywords":["강령: 가치·입장 제시","숙의: 대안 논의·조정","설계: 교육과정 구성"],"kind":"절차"},{"id":"edu-009-q2","prompt":"학교 교육과정 개발 회의에서 참여자들의 가치 판단이 충돌할 때 워커 모형의 숙의 단계에서 취할 활동을 설명하시오.","answer":"참여자들의 서로 다른 가치와 근거를 드러내어 논의하고, 가능한 교육과정 대안을 비교·검토한 뒤 협의와 조정을 통해 실현 가능한 방향을 모색한다.","keywords":["서로 다른 가치·근거 확인","교육과정 대안 비교·협의·조정"],"kind":"설명"}],"source":{"document":"교육학_261019_163033.pdf","page":6,"status":"필기 원문 참조·핵심 개념 수동 요약","note":"요약·문제는 제작 편집이며 원문 직인용이나 공식 답안이 아닙니다."}},{"id":"edu-010","area":"교육과정","title":"스킬벡의 학교중심 교육과정 개발","page":6,"summary":"상황 분석을 시작점으로 하는 학교 수준의 교육과정 개발을 학습한다.","sections":[{"heading":"핵심 과정","text":"상황분석 → 목표 설정 → 프로그램 구성 → 해석과 실행 → 평가와 재검토."},{"heading":"특징","text":"학교 안팎의 상황을 분석하고 개발 단계를 유연하게 운영한다."}],"questions":[{"id":"edu-010-q1","prompt":"스킬벡의 학교중심 교육과정 개발 모형의 핵심 절차를 제시하시오.","answer":"상황분석 → 목표설정 → 프로그램 구성 → 해석과 실행 → 평가·재검토이다.","keywords":["상황분석","목표설정","프로그램","실행","평가"],"kind":"절차"}],"source":{"document":"교육학_261019_163033.pdf","page":6,"status":"필기 원문 참조·핵심 개념 수동 요약","note":"요약·문제는 제작 편집이며 원문 직인용이나 공식 답안이 아닙니다."}},{"id":"edu-011","area":"교육방법","title":"강의법","page":10,"summary":"강의법은 지식을 비교적 짧은 시간에 체계적으로 제시할 수 있지만, 참여·상호작용 활동을 충분히 설계하지 않으면 수동적 학습이 나타날 수 있다.","sections":[{"heading":"장점","text":"학습자 집단에 주요 개념·정보를 구조화하여 효율적으로 제시하기 쉽다. 이해 여부를 확인하는 발문·예시를 병행할 수 있다."},{"heading":"단점","text":"학습자의 활동·상호작용이 부족한 방식으로 운영하면 수동적 참여가 나타날 수 있다. 강의법 자체가 언제나 수동적 학습을 초래하는 것은 아니다."}],"questions":[{"id":"edu-011-q1","prompt":"강의법의 장점과 단점을 각각 한 가지 설명하시오.","answer":"장점: 비교적 짧은 시간에 많은 내용을 체계적으로 전달하기 쉽다. 단점: 학습자 참여를 위한 활동을 병행하지 않으면 수동적인 학습이 나타날 수 있다.","keywords":["장점: 다수 학습자에게 체계적 전달","단점: 참여 설계가 부족하면 수동적 학습 가능"],"kind":"비교"}],"source":{"document":"교육학_261019_163033.pdf","page":10,"status":"필기 원문 참조·핵심 개념 수동 요약","note":"요약·문제는 제작 편집이며 원문 직인용이나 공식 답안이 아닙니다."}},{"id":"edu-012","area":"교육방법","title":"토의법","page":10,"summary":"학습자의 참여, 문제해결 및 토의 유형을 구분한다.","sections":[{"heading":"특징","text":"학습자의 참여와 상호작용을 통해 다양한 관점을 검토하고 문제 해결을 촉진할 수 있다. 효과는 토의 설계와 진행에 따라 달라진다."},{"heading":"토의 유형","text":"원탁식 토의, 배심 토의, 공개 토의, 대담 토의, 세미나, 버즈 토의 등을 구분한다."}],"questions":[{"id":"edu-012-q1","prompt":"토의법의 교육적 특징을 두 가지 서술하시오.","answer":"① 다양한 의견과 근거를 비교·검토하여 사고를 심화할 수 있다. ② 학습자가 토의에 직접 참여하여 의사소통·경청·협력 능력을 연습할 수 있다. 효과는 과제와 진행 방식에 따라 달라진다.","keywords":["다양한 의견·근거 비교","참여를 통한 의사소통·경청·협력"],"kind":"설명"}],"source":{"document":"교육학_261019_163033.pdf","page":10,"status":"필기 원문 참조·핵심 개념 수동 요약","note":"요약·문제는 제작 편집이며 원문 직인용이나 공식 답안이 아닙니다."}},{"id":"edu-013","area":"교육방법","title":"프로젝트법","page":10,"summary":"학습자의 주제 선정과 실제 문제해결 과정을 살핀다.","sections":[{"heading":"특징","text":"학습자가 주제를 선정하고 학습 방법을 구성하는 자기주도적 활동이다."},{"heading":"학습 과정","text":"목적 설정(학습 목표·주제 명료화) → 계획 수립 → 실행 → 평가가 대표적 흐름이다. 실제 프로젝트에서는 상황에 따라 과정을 반복하거나 조정할 수 있다."},{"heading":"장단점","text":"실제 문제와의 연결·통합적 학습에 유리하지만 시간·물적 자원이 많이 든다."}],"questions":[{"id":"edu-013-q1","prompt":"프로젝트법의 대표적인 학습 진행 과정을 순서대로 제시하시오.","answer":"목적 설정 → 계획 수립 → 실행 → 평가의 흐름으로 정리할 수 있다. 실제 프로젝트 수업에서는 과정이 반복되거나 조정될 수 있다.","keywords":["목적 설정","계획","실행","평가"],"kind":"절차"},{"id":"edu-013-q2","prompt":"프로젝트법의 장점과 한계를 각각 설명하시오.","answer":"실제 문제와 연결하여 통합적 사고를 기를 수 있지만 시간과 물적 자원이 많이 필요하다.","keywords":["실제 문제","통합적 사고","자원"],"kind":"비교"}],"source":{"document":"교육학_261019_163033.pdf","page":10,"status":"필기 원문 참조·핵심 개념 수동 요약","note":"요약·문제는 제작 편집이며 원문 직인용이나 공식 답안이 아닙니다."}},{"id":"edu-014","area":"협동학습","title":"STAD 성취과제분담학습","page":14,"summary":"개별 성취와 팀 보상을 결합하는 협동학습 모형이다.","sections":[{"heading":"주요 요소","text":"집단 보상, 개별적 책무성, 성공 기회의 균등분배."},{"heading":"운영 과정","text":"교사의 수업 내용 제시 → 팀 학습(이질 집단의 상호 도움) → 개인 퀴즈 → 개인 향상 점수 산출 → 팀 인정·보상."}],"questions":[{"id":"edu-014-q1","prompt":"STAD의 핵심 요소 세 가지를 서술하시오.","answer":"집단 보상, 개별적 책무성, 성공 기회의 균등분배이다.","keywords":["집단 보상","개별적 책무성","성공 기회"],"kind":"개념"},{"id":"edu-014-q2","prompt":"STAD의 운영 과정을 순서대로 설명하시오.","answer":"교사가 학습 내용을 제시한 뒤 이질적인 팀에서 함께 공부한다. 이어 개인별 퀴즈를 실시하고 이전 성취에 대한 향상 점수를 계산하여 팀 인정·보상에 활용한다.","keywords":["교사 수업 제시","팀 학습","개인 퀴즈","향상 점수","팀 인정·보상"],"kind":"절차"}],"source":{"document":"교육학_261019_163033.pdf","page":14,"status":"필기 원문 참조·핵심 개념 수동 요약","note":"요약·문제는 제작 편집이며 원문 직인용이나 공식 답안이 아닙니다."}},{"id":"edu-015","area":"협동학습","title":"직소(Jigsaw) 모형","page":14,"summary":"모집단·전문가집단 활동을 통해 지식을 상호 가르치는 모형이다.","sections":[{"heading":"운영 과정","text":"모집단 활동 → 전문가 활동 → 모집단 재소집 → 평가."},{"heading":"전문가 집단","text":"동일 주제 담당자들이 모여 학습 내용을 정교화한다."},{"heading":"모집단 재소집","text":"전문가집단에서 학습한 지식을 원래 집단에 전달한다."}],"questions":[{"id":"edu-015-q1","prompt":"직소 협동학습의 대표적인 운영 흐름을 설명하시오.","answer":"모집단에서 학습 주제를 분담한 뒤 전문가집단에서 담당 내용을 학습하고, 모집단으로 돌아와 서로 가르친 후 학습 결과를 확인한다. 세부 평가·보상 방식은 직소 모형의 변형에 따라 달라질 수 있다.","keywords":["모집단 주제 분담","전문가집단","모집단 상호교수","학습 결과 확인"],"kind":"절차"},{"id":"edu-015-q2","prompt":"직소 수업에서 한 학생이 담당 내용을 충분히 학습하지 못한 채 모집단에 돌아온 경우, 전문가집단과 모집단에서 각각 어떤 지원이 가능한지 설명하시오.","answer":"전문가집단에서는 해당 학생이 담당 내용을 이해하고 설명할 수 있도록 서로 자료를 확인하고 도와야 한다. 모집단에서는 다른 학생들이 설명을 듣고 질문·확인을 통해 학습 내용을 공유하여 구성원 모두의 이해를 돕는다.","keywords":["전문가집단: 담당 내용 이해·설명 준비 지원","모집단: 상호 설명·질문으로 이해 공유"],"kind":"비교"}],"source":{"document":"교육학_261019_163033.pdf","page":14,"status":"필기 원문 참조·핵심 개념 수동 요약","note":"요약·문제는 제작 편집이며 원문 직인용이나 공식 답안이 아닙니다."}},{"id":"edu-016","area":"협동학습","title":"Co-op Co-op 자율적 협동학습","page":14,"summary":"Co-op Co-op은 학습 주제를 소주제와 개인별 미니 주제로 나누어 탐구한 뒤, 개인 학습을 팀 학습으로 통합하고 학급 전체에 공유하는 협동학습 모형이다.","sections":[{"heading":"진행 방식","text":"학급 수준의 주제를 바탕으로 팀이 소주제를 맡고, 팀원들이 개인별 미니 주제를 분담해 조사한다. 이후 팀 내 발표·종합을 거쳐 팀별 전체 발표와 공유를 진행한다. 수업에 따라 준비·평가 등 세부 운영이 달라질 수 있다."},{"heading":"평가 방식","text":"동료평가와 교사평가 등을 활용한다."}],"questions":[{"id":"edu-016-q1","prompt":"Co-op Co-op에서 학습자들이 소주제를 학습하는 방식을 설명하시오.","answer":"팀이 소주제를 맡아 팀원별로 미니 주제를 분담·탐구한다. 각자의 결과를 팀 안에서 발표·종합하고, 통합한 내용을 학급 전체에 발표·공유한다.","keywords":["팀의 소주제 담당","개인별 미니 주제 탐구","팀 내 발표·종합","학급 전체 발표·공유"],"kind":"절차"}],"source":{"document":"교육학_261019_163033.pdf","page":14,"status":"필기 원문 참조·핵심 개념 수동 요약","note":"요약·문제는 제작 편집이며 원문 직인용이나 공식 답안이 아닙니다."}},{"id":"edu-017","area":"교육평가","title":"수행평가","page":18,"summary":"학습자가 지식·기능을 실제로 수행하거나 산출물을 제작한 증거를 바탕으로 성취를 평가한다.","sections":[{"heading":"핵심 개념","text":"학습자의 수행 과정 또는 결과물 등 관찰 가능한 증거를 활용해 학습목표 도달 정도를 판단한다. 실제적 과제가 자주 활용되지만 모든 수행평가가 반드시 현실 상황을 그대로 재현하는 것은 아니다."},{"heading":"특징","text":"선택형 문항 외에 산출물 작성과 행동 수행 등 다양한 수행의 증거를 활용한다."}],"questions":[{"id":"edu-017-q1","prompt":"수행평가의 개념과 평가 대상을 설명하시오.","answer":"수행평가는 학습자가 지식과 기능을 실제로 수행하거나 산출물을 구성하는 모습을 증거로 삼아 성취를 판단하는 평가이다. 과제의 성격에 따라 수행 과정, 결과물 또는 둘 모두를 평가할 수 있다.","keywords":["수행·산출물의 증거","성취 판단","과정 또는 결과"],"kind":"설명"}],"source":{"document":"교육학_261019_163033.pdf","page":18,"status":"필기 원문 참조·핵심 개념 수동 요약","note":"요약·문제는 제작 편집이며 원문 직인용이나 공식 답안이 아닙니다."}},{"id":"edu-018","area":"교육평가","title":"루브릭","page":18,"summary":"평가기준과 수행 수준별 질적 기술을 제시하는 채점 도구이다.","sections":[{"heading":"핵심 개념","text":"학습자의 학습 성과를 평가하기 위해 기준과 수행 수준을 구체화한 채점 도구."},{"heading":"구성 요소","text":"과제·학습 목표와 관련된 평가 영역/특성, 수행 수준, 각 수준에 대한 구체적 기술 등."}],"questions":[{"id":"edu-018-q1","prompt":"루브릭의 의미와 주요 구성 요소를 설명하시오.","answer":"루브릭은 수행을 평가하는 채점 기준표로 평가 영역·수행 수준·각 수준에 대한 기술 등을 담는다.","keywords":["채점 기준","평가 영역","수행 수준","기술"],"kind":"개념"},{"id":"edu-018-q2","prompt":"루브릭 활용 시 유의할 점을 한 가지 설명하시오.","answer":"평가 영역과 수행 수준이 학습 목표 및 과제의 성격과 일치하도록 구체적이고 이해 가능하게 작성해야 한다.","keywords":["학습 목표·과제와 일치하는 명료한 기준"],"kind":"적용"}],"source":{"document":"교육학_261019_163033.pdf","page":18,"status":"필기 원문 참조·핵심 개념 수동 요약","note":"요약·문제는 제작 편집이며 원문 직인용이나 공식 답안이 아닙니다."}},{"id":"edu-019","area":"교육평가","title":"평가도구의 타당도","page":18,"summary":"평가 점수의 특정 목적에 따른 해석과 사용을 뒷받침하는 다양한 타당화 증거를 이해한다.","sections":[{"heading":"타당도","text":"타당도는 평가 점수의 의도된 해석과 사용이 이론과 경험적 증거로 얼마나 정당화되는지를 뜻한다."},{"heading":"주요 구분","text":"내용 관련 증거, 응답 과정에 관한 증거, 내적 구조에 관한 증거, 다른 변수와의 관계에 관한 증거, 검사 결과 사용의 영향에 관한 근거 등을 종합적으로 검토한다. 전통적 교육학 교재의 내용·준거·구인 타당도 구분과 구별해서 이해한다."}],"questions":[{"id":"edu-019-q1","prompt":"교육평가에서 타당도의 의미를 점수의 해석과 사용 관점에서 설명하시오.","answer":"타당도는 평가 점수를 특정 목적에 맞게 해석하고 사용하는 것이 증거와 이론에 의해 얼마나 뒷받침되는가에 관한 것이다. 검사가 단순히 특정 내용을 포함했는지뿐 아니라 그 결과를 어떻게 해석·활용하는지 검토해야 한다.","keywords":["점수의 해석","점수의 사용","증거 또는 근거","정당화"],"kind":"개념"},{"id":"edu-019-q2","prompt":"내용·준거 관련·구인 타당도와 관련된 증거를 각각 어떻게 검토하는지 설명하시오.","answer":"내용 관련 증거는 평가 문항과 과제가 측정 대상 내용 영역을 적절하게 대표하는지, 준거 관련 증거는 외부 준거와의 관계가 점수 해석을 지지하는지, 구인 관련 증거는 의도한 심리적 구인에 대한 점수 해석을 지지하는지 검토한다. 이들은 서로 완전히 분리된 타당도 점수라기보다 타당화에 활용되는 증거로 이해하는 것이 적절하다.","keywords":["내용 영역 대표성","외부 준거와의 관계","구인 해석을 뒷받침하는 증거"],"kind":"개념"}],"source":{"document":"교육학_261019_163033.pdf","page":18,"status":"필기 원문 참조·핵심 개념 수동 요약","note":"요약·문제는 제작 편집이며 원문 직인용이나 공식 답안이 아닙니다."}},{"id":"edu-020","area":"교육행정","title":"관료적 조직","page":20,"summary":"계층적 권한과 합법적·합리적 지배에 기초한 조직이다.","sections":[{"heading":"정의","text":"계층적 권한과 합법적·합리적 지배가 제도화된 조직."},{"heading":"특성","text":"분업과 전문화, 운영절차의 규칙성, 권한의 위계, 몰인정성, 규정 지향성 등이 정리되어 있다."}],"questions":[{"id":"edu-020-q1","prompt":"관료적 조직의 특징을 두 가지 제시하시오.","answer":"① 업무를 전문화된 역할로 분업한다. ② 권한의 위계를 두고 공식 규정과 절차에 따라 업무를 처리한다.","keywords":["전문화·분업","권한 위계 및 공식 규칙"],"kind":"개념"}],"source":{"document":"교육학_261019_163033.pdf","page":20,"status":"필기 원문 참조·핵심 개념 수동 요약","note":"요약·문제는 제작 편집이며 원문 직인용이나 공식 답안이 아닙니다."}},{"id":"edu-021","area":"교육행정","title":"이완조직","page":20,"summary":"조직 구성요소 간 연결이 느슨하면서도 상호 영향을 주는 조직 관점이다.","sections":[{"heading":"개념","text":"조직 구성요소들이 서로 독립적인 자율성을 가지되 상호 영향을 주는 구조를 의미한다."},{"heading":"교육적 의미","text":"학교 안의 교사·교실·학년·교과 등 하위 체계의 자율성과 부분적인 연결을 이해하는 데 사용된다."}],"questions":[{"id":"edu-021-q1","prompt":"이완조직의 의미를 서술하시오.","answer":"조직의 하위 단위들이 비교적 느슨하게 결합되어 자율성을 유지하면서도 상호 영향을 주는 조직 구조이다.","keywords":["느슨한 결합","자율성","상호 영향"],"kind":"개념"}],"source":{"document":"교육학_261019_163033.pdf","page":20,"status":"필기 원문 참조·핵심 개념 수동 요약","note":"요약·문제는 제작 편집이며 원문 직인용이나 공식 답안이 아닙니다."}},{"id":"edu-022","area":"교육심리","title":"프로이트 성격의 구조","page":1,"summary":"프로이트의 정신분석 이론은 원초아·자아·초자아의 상호작용으로 성격을 설명하는 고전적 이론적 틀이다. 이를 실증적으로 확정된 성격의 물리적 구성요소로 이해하지 않는다.","sections":[{"heading":"원초아","text":"쾌락원리에 따라 즉각적인 욕구 충족을 추구한다."},{"heading":"자아","text":"현실원리에 따라 욕구와 환경의 요구를 중재한다."},{"heading":"초자아","text":"내면화된 도덕규범과 이상을 반영한다."}],"questions":[{"id":"edu-022-q1","prompt":"프로이트의 성격 구조 세 요소를 구분하시오.","answer":"원초아는 쾌락원리에 따라 욕구 충족을 추구하고, 자아는 현실원리에 따라 조절하며, 초자아는 도덕적 규범을 반영한다.","keywords":["원초아","자아","초자아"],"kind":"비교"}],"source":{"document":"교육학_261019_163033.pdf","page":1,"status":"필기 판독·문맥 기반 편집 요약","note":"학습용 재구성 자료이며 필기 원문의 완전한 전사는 아닙니다."}},{"id":"edu-023","area":"교육심리","title":"피아제 인지발달 단계","page":1,"summary":"인지발달의 일반적 단계를 구분하고 사고 특성 변화를 이해한다.","sections":[{"heading":"발달 단계","text":"감각운동기 → 전조작기 → 구체적 조작기 → 형식적 조작기."},{"heading":"교수·학습 시사점","text":"학습자의 인지적 발달 수준과 선행 도식을 고려해 과제를 조직한다."}],"questions":[{"id":"edu-023-q1","prompt":"피아제의 인지발달 4단계를 순서대로 제시하시오.","answer":"감각운동기, 전조작기, 구체적 조작기, 형식적 조작기이다.","keywords":["감각운동기","전조작기","구체적 조작기","형식적 조작기"],"kind":"절차"}],"source":{"document":"교육학_261019_163033.pdf","page":1,"status":"필기 판독·문맥 기반 편집 요약","note":"학습용 재구성 자료이며 필기 원문의 완전한 전사는 아닙니다."}},{"id":"edu-024","area":"교육과정","title":"잠재적 교육과정과 영 교육과정","page":7,"summary":"학교생활에서 암묵적으로 학습하는 것과 교육과정에서 배제된 것을 구분한다.","sections":[{"heading":"잠재적 교육과정","text":"공식적 목표로 명시되지 않았더라도 학교의 규범·관계·문화 속에서 경험하며 학습하는 내용."},{"heading":"영 교육과정","text":"교육과정에서 다루지 않아 학생에게 학습 기회가 제공되지 않는 내용."}],"questions":[{"id":"edu-024-q1","prompt":"잠재적 교육과정과 영 교육과정을 비교하시오.","answer":"잠재적 교육과정은 학교생활에서 암묵적으로 학습하는 경험이고, 영 교육과정은 학교에서 가르치지 않아 학습 기회를 얻지 못하는 내용이다.","keywords":["암묵적 학습","가르치지 않음","학습 기회"],"kind":"비교"}],"source":{"document":"교육학_261019_163033.pdf","page":7,"status":"필기 판독·문맥 기반 편집 요약","note":"학습용 재구성 자료이며 필기 원문의 완전한 전사는 아닙니다."}},{"id":"edu-025","area":"교육방법","title":"문제중심학습(PBL)","page":11,"summary":"실제적·비구조화된 문제를 통해 자기주도적 탐구와 협력적 해결을 촉진한다.","sections":[{"heading":"핵심 특징","text":"실제적이고 정답이 단일하지 않은 문제를 출발점으로 삼으며, 학습자가 필요한 지식을 탐색한다."},{"heading":"교사의 역할","text":"정답을 직접 제공하기보다 학습자가 문제를 정의하고 탐구하도록 촉진한다."}],"questions":[{"id":"edu-025-q1","prompt":"문제중심학습의 핵심 특징을 설명하시오.","answer":"실제적·비구조화된 문제를 중심으로 학습자가 자기주도적으로 정보를 탐색하고 협력하여 해결안을 구성한다.","keywords":["비구조화된 문제","자기주도","협력"],"kind":"개념"},{"id":"edu-025-q2","prompt":"문제중심학습에서 학생들이 문제 해결 도중 막혔을 때 교사가 할 수 있는 지원 행동을 두 가지 구체적으로 서술하시오.","answer":"① 해결책을 바로 제시하지 않고 학생이 문제의 조건과 쟁점을 다시 확인하도록 발문한다. ② 관련 자료를 탐색할 방향을 안내하고 학생들이 근거를 들어 서로 설명하도록 촉진한다.","keywords":["문제 재정의를 돕는 발문","정보 탐색 및 근거 중심 협력 촉진"],"kind":"적용"}],"source":{"document":"교육학_261019_163033.pdf","page":11,"status":"필기 판독·문맥 기반 편집 요약","note":"학습용 재구성 자료이며 필기 원문의 완전한 전사는 아닙니다."}},{"id":"edu-026","area":"교육방법","title":"켈러의 ARCS 동기설계","page":13,"summary":"학습 동기를 주의·관련성·자신감·만족감의 네 요소로 설명한다.","sections":[{"heading":"주의집중","text":"호기심을 유발하고 주의를 지속하도록 자극한다."},{"heading":"관련성","text":"학습 목표와 개인의 필요·경험을 연결한다."},{"heading":"자신감","text":"성공 기대와 통제감을 형성하도록 난이도 및 피드백을 조절한다."},{"heading":"만족감","text":"성취 결과에 대한 내재적·외재적 만족을 지원한다."}],"questions":[{"id":"edu-026-q1","prompt":"ARCS 동기설계의 네 요소를 쓰시오.","answer":"주의집중, 관련성, 자신감, 만족감이다.","keywords":["주의집중","관련성","자신감","만족감"],"kind":"개념"},{"id":"edu-026-q2","prompt":"자신감과 관련성을 높일 교수 전략을 각각 제시하시오.","answer":"자신감은 성공 가능한 도전 과제와 명료한 기준을 제공하고, 관련성은 학습내용을 학습자의 목표와 경험에 연결하여 높인다.","keywords":["성공 기대","명료한 기준","경험 연결"],"kind":"적용"}],"source":{"document":"교육학_261019_163033.pdf","page":13,"status":"필기 판독·문맥 기반 편집 요약","note":"학습용 재구성 자료이며 필기 원문의 완전한 전사는 아닙니다."}},{"id":"edu-027","area":"교육평가","title":"진단평가·형성평가·총괄평가","page":19,"summary":"평가의 시점과 목적에 따라 교수 전·중·후의 평가를 구별한다.","sections":[{"heading":"진단평가","text":"학습 전 선수학습 정도와 결손을 파악해 출발점을 확인한다."},{"heading":"형성평가","text":"학습 도중 성취 정도를 점검하여 교수·학습을 수정한다."},{"heading":"총괄평가","text":"일정 학습이 끝난 후 목표 달성 여부를 종합적으로 판단한다."}],"questions":[{"id":"edu-027-q1","prompt":"진단·형성·총괄평가의 목적을 비교하시오.","answer":"진단평가는 출발점 파악, 형성평가는 학습 중 피드백과 수정, 총괄평가는 학습 후 목표 도달 정도의 종합 판단을 목적으로 한다.","keywords":["출발점","피드백","종합 판단"],"kind":"비교"}],"source":{"document":"교육학_261019_163033.pdf","page":19,"status":"필기 판독·문맥 기반 편집 요약","note":"학습용 재구성 자료이며 필기 원문의 완전한 전사는 아닙니다."}},{"id":"edu-028","area":"교육평가","title":"평가도구의 신뢰도","page":19,"summary":"측정 결과의 일관성에 대한 개념을 학습한다.","sections":[{"heading":"의미","text":"동일하거나 유사한 조건에서 측정할 때 결과가 일관되는 정도."},{"heading":"주요 방법","text":"재검사 신뢰도, 동형검사 신뢰도, 반분 신뢰도, 내적 합치도 등을 활용한다."}],"questions":[{"id":"edu-028-q1","prompt":"신뢰도의 의미와 추정 방법을 두 가지 이상 설명하시오.","answer":"신뢰도는 반복적 측정에서 점수가 일관되게 나타나는 정도이다. ① 재검사 신뢰도는 같은 검사를 시간 간격을 두고 반복해 점수의 안정성을 검토한다. ② 내적 합치도는 한 검사 문항들이 관련된 구인을 일관되게 측정하는 정도를 검토한다. 이 밖에 동형검사·반분 방법도 활용할 수 있다.","keywords":["점수의 일관성","재검사: 시간에 따른 안정성","내적 합치도: 문항 간 일관성"],"kind":"개념"}],"source":{"document":"교육학_261019_163033.pdf","page":19,"status":"필기 판독·문맥 기반 편집 요약","note":"학습용 재구성 자료이며 필기 원문의 완전한 전사는 아닙니다."}},{"id":"edu-029","area":"교육행정","title":"변혁적 지도성","page":21,"summary":"구성원의 동기와 조직의 발전을 이끄는 변화 지향적 리더십이다.","sections":[{"heading":"핵심 요소","text":"이상적 영향력, 영감적 동기부여, 지적 자극, 개별적 배려."},{"heading":"학교 적용","text":"공유 비전과 교사 전문성 개발, 협력과 혁신을 지원한다."}],"questions":[{"id":"edu-029-q1","prompt":"변혁적 지도성의 주요 요소를 제시하시오.","answer":"이상적 영향력, 영감적 동기부여, 지적 자극, 개별적 배려이다.","keywords":["이상적 영향력","영감적 동기부여","지적 자극","개별적 배려"],"kind":"개념"}],"source":{"document":"교육학_261019_163033.pdf","page":21,"status":"필기 판독·문맥 기반 편집 요약","note":"학습용 재구성 자료이며 필기 원문의 완전한 전사는 아닙니다."}},{"id":"edu-030","area":"교육행정","title":"임상장학","page":22,"summary":"교사의 수업을 공동으로 분석하고 개선하기 위한 장학 방식이다.","sections":[{"heading":"주요 흐름","text":"사전 협의 → 수업 관찰 → 사후 협의 및 피드백."},{"heading":"특징","text":"실제 수업 관찰 자료에 근거해 교사와 장학 담당자가 협력적으로 수업을 개선한다."}],"questions":[{"id":"edu-030-q1","prompt":"임상장학의 절차와 핵심 특징을 설명하시오.","answer":"사전 협의, 수업 관찰, 사후 협의 및 피드백을 거치며, 실제 수업 자료를 바탕으로 교사와 장학 담당자가 협력한다.","keywords":["사전 협의","수업 관찰","사후 협의","협력"],"kind":"절차"}],"source":{"document":"교육학_261019_163033.pdf","page":22,"status":"필기 판독·문맥 기반 편집 요약","note":"학습용 재구성 자료이며 필기 원문의 완전한 전사는 아닙니다."}},{"id":"edu-031","area":"학습이론","title":"학습 전이와 형식도야설","page":3,"summary":"앞서 배운 지식·기능이 새로운 과제 수행을 촉진하거나 방해할 수 있는 학습 전이와 형식도야설을 구분한다.","sections":[{"heading":"학습 전이","text":"이전 학습이 새로운 상황의 학습이나 수행에 영향을 미치는 현상이다. 새로운 학습을 촉진하는 정적 전이와 간섭·오류를 일으키는 부적 전이가 있다."},{"heading":"형식도야설","text":"기억력·추리력·상상력 등 정신능력이 훈련을 통해 단련될 수 있다는 관점."}],"questions":[{"id":"edu-031-q1","prompt":"학습 전이의 의미를 설명하시오.","answer":"이전 학습이 새로운 과제의 학습 또는 수행에 영향을 미치는 현상이다. 새로운 과제를 더 잘 수행하도록 돕는 정적 전이와 오히려 방해하는 부적 전이가 모두 가능하다.","keywords":["이전 학습","새로운 과제","정적 전이","부적 전이"],"kind":"개념"},{"id":"edu-031-q2","prompt":"형식도야설의 학습 관점을 요약하시오.","answer":"기억력·추리력 등의 정신능력이 훈련에 의해 단련되어 다른 학습에도 도움을 준다는 관점이다.","keywords":["정신능력","훈련","전이"],"kind":"설명"}],"source":{"document":"교육학_261019_163033.pdf","page":3,"status":"필기 이미지 직접 판독·문맥 편집","note":"해당 쪽의 판독 가능한 내용을 서술형 학습용으로 편집했으며, 원문 전체 전사나 공식 정답은 아닙니다."}},{"id":"edu-032","area":"학습이론","title":"반두라의 관찰학습","page":3,"summary":"타인의 행동을 관찰·모방하는 학습의 과정과 자기효능감의 역할을 설명한다.","sections":[{"heading":"관찰학습의 과정","text":"주의집중 → 파지 → 재생 → 동기화."},{"heading":"자기효능감","text":"자신이 어떤 일을 해낼 수 있다는 믿음."},{"heading":"효능감 신장을 위한 과제 설계","text":"작게 성공할 수 있는 과제, 유사한 모델의 수행 관찰, 적절한 격려와 피드백 등을 고려한다."}],"questions":[{"id":"edu-032-q1","prompt":"반두라의 관찰학습 네 과정을 순서대로 쓰시오.","answer":"주의집중, 파지, 재생, 동기화이다.","keywords":["주의집중","파지","재생","동기화"],"kind":"절차"},{"id":"edu-032-q2","prompt":"자기효능감을 높이기 위한 교수·학습 방안을 두 가지 제시하시오.","answer":"① 난이도를 조정한 과제와 구체적인 피드백으로 직접적인 성공 경험을 제공한다. ② 자신과 비슷한 또래가 과제를 성공적으로 수행하는 모습을 관찰하도록 하여 대리 경험을 제공한다.","keywords":["직접 성공 경험","또래 모델의 대리 경험"],"kind":"적용"}],"source":{"document":"교육학_261019_163033.pdf","page":3,"status":"필기 이미지 직접 판독·문맥 편집","note":"해당 쪽의 판독 가능한 내용을 서술형 학습용으로 편집했으며, 원문 전체 전사나 공식 정답은 아닙니다."}},{"id":"edu-033","area":"학습동기","title":"내적 동기와 외적 동기","page":3,"summary":"행동을 유발하는 동기의 원천을 개인 내부의 흥미와 외부적 보상으로 구분한다.","sections":[{"heading":"내적 동기","text":"행동 자체에서 얻는 흥미·즐거움·만족을 이유로 행동하는 동기."},{"heading":"외적 동기","text":"외부의 보상이나 처벌 등 행동 외부의 결과를 이유로 행동하는 동기."}],"questions":[{"id":"edu-033-q1","prompt":"내적 동기와 외적 동기를 비교하시오.","answer":"내적 동기는 활동 자체의 흥미나 즐거움에서 비롯된다. 외적 동기는 활동과 구별되는 결과나 가치를 위해 행동하는 것으로, 외부 보상·처벌뿐 아니라 학습자가 개인적으로 중요하다고 받아들인 목표나 가치에 의해서도 나타날 수 있다.","keywords":["내적 동기: 활동 자체의 흥미","외적 동기: 활동과 구별되는 결과·가치","외적 동기의 내면화 가능성"],"kind":"비교"}],"source":{"document":"교육학_261019_163033.pdf","page":3,"status":"필기 이미지 직접 판독·문맥 편집","note":"해당 쪽의 판독 가능한 내용을 서술형 학습용으로 편집했으며, 원문 전체 전사나 공식 정답은 아닙니다."}},{"id":"edu-034","area":"학습동기","title":"자기결정성이론의 기본 욕구","page":3,"summary":"자기결정성이론에서 강조하는 세 가지 기본 심리 욕구를 구분한다.","sections":[{"heading":"자율성","text":"자신의 행동을 자발적으로 선택하고, 그 행동의 가치나 이유를 스스로 수용하며 주체적으로 행동하려는 욕구이다. 단순히 선택지를 많이 주는 것과 동일하지는 않다."},{"heading":"유능성","text":"자신의 능력을 발휘하고 과제를 성공적으로 수행하려는 욕구."},{"heading":"관계성","text":"타인과 연결되고 소속감을 느끼고자 하는 욕구."}],"questions":[{"id":"edu-034-q1","prompt":"자기결정성이론의 기본 심리 욕구 세 가지와 의미를 설명하시오.","answer":"자율성은 자신의 행동을 자발적으로 선택하고 그 가치를 스스로 수용하여 행동하고자 하는 욕구, 유능성은 환경과 효과적으로 상호작용하고 역량을 발휘하고자 하는 욕구, 관계성은 타인과 연결되고 소속감을 느끼고자 하는 욕구이다.","keywords":["자율성","유능성","관계성"],"kind":"개념"},{"id":"edu-034-q2","prompt":"학습자의 자기결정성을 지원하기 위한 수업 요소를 제시하시오.","answer":"학생의 관점을 존중하고 수업 활동의 이유를 설명하며 선택 기회를 제공해 자율성을 지원한다. 학습 가능한 도전 과제와 구체적 피드백으로 유능성을 지원하고, 존중·협력의 관계를 통해 관계성을 지원한다.","keywords":["자율성: 이유 설명·관점 존중·선택","유능성: 도전·구체적 피드백","관계성: 존중·소속감"],"kind":"적용"}],"source":{"document":"교육학_261019_163033.pdf","page":3,"status":"필기 이미지 직접 판독·문맥 편집","note":"해당 쪽의 판독 가능한 내용을 서술형 학습용으로 편집했으며, 원문 전체 전사나 공식 정답은 아닙니다."}},{"id":"edu-035","area":"학습동기","title":"기대-가치 이론","page":3,"summary":"기대-가치 이론은 과제에 대한 성공 기대와 주관적 과제 가치가 학습 선택·참여에 영향을 준다고 설명한다. 과제 가치에는 중요성·흥미·유용성뿐 아니라 지각된 비용도 관련된다.","sections":[{"heading":"성공 기대","text":"과제를 성공적으로 수행할 수 있다는 기대와 자신의 수행 능력에 대한 믿음."},{"heading":"과제 가치","text":"주관적 과제 가치는 성취가 자신에게 중요한 정도(성취 가치), 과제 자체의 흥미·즐거움(내재 가치), 다른 목표에 대한 유용성(유용 가치), 과제 수행에 따르는 노력·시간·정서적 부담 등의 지각된 비용을 함께 고려한다."}],"questions":[{"id":"edu-035-q1","prompt":"기대-가치 이론에서 학습 동기의 두 주요 요소는 무엇인가?","answer":"두 핵심 요소는 ① 성공 기대: 과제를 성공적으로 수행할 수 있다는 믿음, ② 주관적 과제 가치: 과제의 중요성(성취 가치), 흥미(내재 가치), 유용성(유용 가치), 수행에 수반되는 지각된 비용을 포괄하는 판단이다.","keywords":["성공 기대","주관적 과제 가치","중요성·흥미·유용성","지각된 비용"],"kind":"개념"}],"source":{"document":"교육학_261019_163033.pdf","page":3,"status":"필기 이미지 직접 판독·문맥 편집","note":"해당 쪽의 판독 가능한 내용을 서술형 학습용으로 편집했으며, 원문 전체 전사나 공식 정답은 아닙니다."}},{"id":"edu-036","area":"학습동기","title":"목표지향성 이론","page":4,"summary":"숙달목표와 수행목표의 차이를 통해 학습자가 과제에 접근하는 이유를 이해한다.","sections":[{"heading":"숙달목표 지향성","text":"과제 자체의 이해, 능력 향상, 새로운 지식 습득에 중점을 둔다."},{"heading":"수행목표 지향성","text":"타인과 비교한 자신의 능력을 입증하려는 수행접근목표와 무능력하게 보이는 것을 피하려는 수행회피목표로 구분할 수 있다."}],"questions":[{"id":"edu-036-q1","prompt":"숙달목표 지향성과 수행목표 지향성을 비교하시오.","answer":"숙달목표 지향성은 이해·숙련과 자신의 능력 향상을 중시하며, 수행목표 지향성은 타인과 비교한 능력의 입증 또는 무능력 노출의 회피에 초점을 둔다. 수행목표는 접근과 회피의 양상으로도 구분된다.","keywords":["숙달: 이해·능력 향상","수행접근: 능력 입증","수행회피: 무능력 노출 회피"],"kind":"비교"}],"source":{"document":"교육학_261019_163033.pdf","page":4,"status":"필기 이미지 직접 판독·문맥 편집","note":"해당 쪽의 판독 가능한 내용을 서술형 학습용으로 편집했으며, 원문 전체 전사나 공식 정답은 아닙니다."}},{"id":"edu-037","area":"학습동기","title":"학습된 무기력","page":4,"summary":"반복된 실패를 자신의 통제 밖으로 인식하면 시도와 동기가 감소할 수 있다.","sections":[{"heading":"핵심 개념","text":"자신이 어떤 행동을 하여도 결과를 바꿀 수 없다고 인식하면 학습 행동을 포기하는 상태."},{"heading":"지도 시사점","text":"학습자가 통제 가능한 전략과 노력에 주목하도록 돕고 작은 성공 경험을 제공한다."}],"questions":[{"id":"edu-037-q1","prompt":"학습된 무기력의 의미와 지도 방안을 설명하시오.","answer":"결과를 통제할 수 없다는 인식 때문에 시도를 포기하는 상태이다. 조절 가능한 전략의 사용과 단계적 성공 경험을 지원한다.","keywords":["통제 불가능 인식","시도 포기","성공 경험"],"kind":"적용"}],"source":{"document":"교육학_261019_163033.pdf","page":4,"status":"필기 이미지 직접 판독·문맥 편집","note":"해당 쪽의 판독 가능한 내용을 서술형 학습용으로 편집했으며, 원문 전체 전사나 공식 정답은 아닙니다."}},{"id":"edu-038","area":"교육심리","title":"장독립형과 장의존형 인지양식","page":4,"summary":"장의존형·장독립형이라는 인지양식의 정보 처리 경향을 비교하며, 어느 한 유형이 전반적으로 우수하다고 단정하지 않는다.","sections":[{"heading":"장의존형","text":"주변 맥락의 영향을 상대적으로 많이 받으며 요소를 전체 장면과 관련지어 지각하는 경향을 뜻한다. 대인관계나 사회적 단서에 민감한 경우가 있다고 설명되지만 개인마다 차이가 있다."},{"heading":"장독립형","text":"주변 맥락과 요소를 구분해 독립적으로 분석하는 경향."},{"heading":"해석상 주의","text":"두 범주는 정보처리 경향을 설명하는 개념으로, 학습자의 지능이나 성취 수준의 우열을 뜻하지 않는다."}],"questions":[{"id":"edu-038-q1","prompt":"장독립형과 장의존형 인지양식을 비교하시오.","answer":"장독립형은 주변 맥락에서 정보를 분리해 분석하는 경향이 있고, 장의존형은 전체 맥락과 사회적 단서의 영향을 상대적으로 많이 받는다.","keywords":["분리·분석","전체 맥락"],"kind":"비교"}],"source":{"document":"교육학_261019_163033.pdf","page":4,"status":"필기 이미지 직접 판독·문맥 편집","note":"해당 쪽의 판독 가능한 내용을 서술형 학습용으로 편집했으며, 원문 전체 전사나 공식 정답은 아닙니다."}},{"id":"edu-039","area":"교육심리","title":"가드너의 다중지능이론","page":4,"summary":"인간의 지능을 하나의 능력으로 환원하지 않고 여러 지능의 조합으로 설명한다.","sections":[{"heading":"핵심 가정","text":"사람마다 서로 다른 지능의 강점이 있으며, 다양한 활동을 통해 지능을 발휘할 수 있다."},{"heading":"교육적 시사점","text":"다중지능이론의 관점에서는 학습 과제나 표현 방식을 다양하게 마련해 학습자가 여러 방식으로 참여할 기회를 제공할 수 있다. 이는 다중지능별로 수업을 맞추면 성취가 반드시 향상된다는 실증적 보장을 뜻하지는 않는다."}],"questions":[{"id":"edu-039-q1","prompt":"다중지능이론의 교육적 시사점을 서술하시오.","answer":"학습자마다 다양한 지능적 강점이 있으므로 표현·활동·평가의 방식을 다양화하여 강점을 활용할 수 있게 한다.","keywords":["다양한 강점","표현 방식","활동 다양화"],"kind":"적용"}],"source":{"document":"교육학_261019_163033.pdf","page":4,"status":"필기 이미지 직접 판독·문맥 편집","note":"해당 쪽의 판독 가능한 내용을 서술형 학습용으로 편집했으며, 원문 전체 전사나 공식 정답은 아닙니다."}},{"id":"edu-040","area":"교육심리","title":"스턴버그의 삼원지능이론","page":5,"summary":"분석적·창의적·실제적 능력을 구분하는 지능 관점을 학습한다.","sections":[{"heading":"분석적 능력","text":"문제를 분석하고 비교·판단하는 능력."},{"heading":"창의적 능력","text":"새로운 생각과 해결 방식을 만들어 내는 능력."},{"heading":"실제적 능력","text":"현실 상황에 적응하거나 환경을 선택·변형하는 능력."}],"questions":[{"id":"edu-040-q1","prompt":"스턴버그의 삼원지능이론의 세 능력을 설명하시오.","answer":"분석적 능력은 분석·판단, 창의적 능력은 새로운 아이디어 생성, 실제적 능력은 상황에 맞춘 적용·적응 능력이다.","keywords":["분석적","창의적","실제적"],"kind":"비교"}],"source":{"document":"교육학_261019_163033.pdf","page":5,"status":"필기 이미지 직접 판독·문맥 편집","note":"해당 쪽의 판독 가능한 내용을 서술형 학습용으로 편집했으며, 원문 전체 전사나 공식 정답은 아닙니다."}},{"id":"edu-041","area":"교육심리","title":"홀랜드의 직업적 성격 유형","page":5,"summary":"홀랜드의 여섯 직업적 흥미 유형(RIASEC)과 개인·환경 적합성 관점을 이해한다.","sections":[{"heading":"RIASEC","text":"현실형(R), 탐구형(I), 예술형(A), 사회형(S), 진취형(E), 관습형(C)."},{"heading":"핵심 관점","text":"개인의 직업적 흥미·성격 특성과 직업 환경 사이의 적합성(congruence)을 고려하여 직업 선택 및 만족·적응을 설명한다. 적합성이 개인의 직업적 성공을 반드시 보장하는 것은 아니다."}],"questions":[{"id":"edu-041-q1","prompt":"홀랜드의 RIASEC 여섯 유형을 쓰시오.","answer":"현실형, 탐구형, 예술형, 사회형, 진취형, 관습형이다.","keywords":["현실형","탐구형","예술형","사회형","진취형","관습형"],"kind":"개념"}],"source":{"document":"교육학_261019_163033.pdf","page":5,"status":"필기 이미지 직접 판독·문맥 편집","note":"해당 쪽의 판독 가능한 내용을 서술형 학습용으로 편집했으며, 원문 전체 전사나 공식 정답은 아닙니다."}},{"id":"edu-042","area":"교육심리","title":"창의성의 주요 구성 요소","page":5,"summary":"창의적 사고의 유창성·융통성·독창성·정교성을 구분한다.","sections":[{"heading":"유창성","text":"정해진 시간 내 많은 아이디어를 생성하는 능력."},{"heading":"융통성","text":"여러 관점이나 범주로 접근하는 능력."},{"heading":"독창성","text":"흔하지 않은 독특한 아이디어를 생성하는 능력."},{"heading":"정교성","text":"아이디어를 구체화·보완하고 세부 내용을 발전시키는 능력."}],"questions":[{"id":"edu-042-q1","prompt":"창의성의 네 구성 요소와 의미를 설명하시오.","answer":"유창성은 많은 아이디어의 생성, 융통성은 범주의 다양성, 독창성은 새롭고 독특한 생각, 정교성은 아이디어의 구체적 발전이다.","keywords":["유창성","융통성","독창성","정교성"],"kind":"비교"}],"source":{"document":"교육학_261019_163033.pdf","page":5,"status":"필기 이미지 직접 판독·문맥 편집","note":"해당 쪽의 판독 가능한 내용을 서술형 학습용으로 편집했으며, 원문 전체 전사나 공식 정답은 아닙니다."}},{"id":"edu-043","area":"교육과정","title":"학문중심 교육과정","page":8,"summary":"교과의 지식 구조와 탐구 방법을 중심으로 교육과정을 조직하는 관점이다.","sections":[{"heading":"특징","text":"학문적 개념·원리·법칙과 지식의 구조를 강조한다."},{"heading":"표상 방식","text":"활동적(행동적)·영상적·상징적 표현 방식에 따라 지식을 나타낼 수 있다."},{"heading":"장점과 한계","text":"지식의 전이·탐구를 촉진할 수 있으나 학습자의 수준과 흥미를 고려한 조정이 필요하다."}],"questions":[{"id":"edu-043-q1","prompt":"학문중심 교육과정이 교과중심 교육과정에 비해 추가로 강조하는 학습 내용의 성격을 설명하시오.","answer":"두 접근 모두 교과 지식을 중시하지만, 학문중심 교육과정은 단순히 교과 내용을 체계적으로 전달하는 데 그치지 않고 교과의 지식 구조와 학자가 지식을 생성·검증하는 탐구 방법의 학습을 강조한다.","keywords":["공통점: 교과 지식 중시","학문중심: 지식 구조 및 탐구 방법 강조"],"kind":"설명"}],"source":{"document":"교육학_261019_163033.pdf","page":8,"status":"필기 이미지 직접 판독·문맥 편집","note":"해당 쪽의 판독 가능한 내용을 서술형 학습용으로 편집했으며, 원문 전체 전사나 공식 정답은 아닙니다."}},{"id":"edu-044","area":"교육과정","title":"인간중심 교육과정","page":8,"summary":"학습자의 자아실현과 전인적 성장을 중시한다.","sections":[{"heading":"핵심 지향","text":"학습자의 자아실현과 전인적 성장에 목적을 둔다."},{"heading":"특징","text":"학습자의 경험, 정서적 발달, 자기 이해를 중시하고 잠재적 교육과정에도 주목한다."}],"questions":[{"id":"edu-044-q1","prompt":"인간중심 교육과정의 핵심 목적을 설명하시오.","answer":"학습자의 자아실현과 전인적 성장을 중시하며 학습자의 경험과 정서적 발달에도 관심을 둔다.","keywords":["자아실현","전인적 성장","경험"],"kind":"개념"}],"source":{"document":"교육학_261019_163033.pdf","page":8,"status":"필기 이미지 직접 판독·문맥 편집","note":"해당 쪽의 판독 가능한 내용을 서술형 학습용으로 편집했으며, 원문 전체 전사나 공식 정답은 아닙니다."}},{"id":"edu-045","area":"교육과정","title":"교육과정 운영의 세 관점","page":8,"summary":"교육과정 실행을 이해하는 충실성·상호적응·생성 관점의 차이를 설명한다.","sections":[{"heading":"충실성 관점","text":"개발된 교육과정을 원래 계획대로 실행하는 것을 중시한다."},{"heading":"상호적응 관점","text":"교육과정의 계획과 실제 학교 상황이 상호작용하면서 실행 과정에서 서로 조정·변형된다고 보는 관점이다."},{"heading":"생성 관점","text":"교사와 학생의 실제 상호작용 속에서 교육과정이 구성될 수 있다고 본다."}],"questions":[{"id":"edu-045-q1","prompt":"교육과정 운영의 충실성·상호적응·생성 관점을 비교하시오.","answer":"① 충실성 관점: 계획·개발된 교육과정을 의도대로 실행했는지에 초점을 둔다. ② 상호적응 관점: 교육과정과 현장의 여건이 실행 과정에서 서로 조정된다고 본다. ③ 생성 관점: 교사와 학생의 실제 교육활동과 상호작용 속에서 교육과정이 구성된다고 본다.","keywords":["계획 실행","상호 조정","현장 생성"],"kind":"비교"}],"source":{"document":"교육학_261019_163033.pdf","page":8,"status":"필기 이미지 직접 판독·문맥 편집","note":"해당 쪽의 판독 가능한 내용을 서술형 학습용으로 편집했으며, 원문 전체 전사나 공식 정답은 아닙니다."}},{"id":"edu-046","area":"교육방법","title":"ADDIE 수업설계 모형","page":9,"summary":"수업을 분석·설계·개발·실행·평가의 과정으로 조직한다.","sections":[{"heading":"분석","text":"학습자·환경·과제와 요구를 분석한다."},{"heading":"설계","text":"목표와 평가·교수 전략의 방향을 설정한다."},{"heading":"개발","text":"교수·학습 자료를 제작하고 점검한다."},{"heading":"실행 및 평가","text":"설계한 수업을 실시하고 성과를 평가·환류한다."}],"questions":[{"id":"edu-046-q1","prompt":"ADDIE 모형의 다섯 단계를 순서대로 설명하시오.","answer":"분석 → 설계 → 개발 → 실행 → 평가이다.","keywords":["분석","설계","개발","실행","평가"],"kind":"절차"},{"id":"edu-046-q2","prompt":"ADDIE의 분석 단계에서 다루는 사항을 제시하시오.","answer":"학습자 특성, 환경, 과제와 요구 등을 분석한다.","keywords":["학습자","환경","과제"],"kind":"설명"}],"source":{"document":"교육학_261019_163033.pdf","page":9,"status":"필기 이미지 직접 판독·문맥 편집","note":"해당 쪽의 판독 가능한 내용을 서술형 학습용으로 편집했으며, 원문 전체 전사나 공식 정답은 아닙니다."}},{"id":"edu-047","area":"교육방법","title":"딕과 캐리의 체제적 교수설계 모형","page":9,"summary":"목표·학습자·평가·교수전략·자료의 관계를 통합적으로 설계한다.","sections":[{"heading":"핵심 흐름","text":"교수목표 확인 → 교수분석 및 학습자 분석 → 수행목표 진술 → 평가도구 개발 → 교수전략 개발 → 교수자료 개발 → 형성평가와 수정."},{"heading":"특징","text":"교수설계를 체제적으로 이해하며 구성 요소 간 피드백과 수정을 중시한다."}],"questions":[{"id":"edu-047-q1","prompt":"딕과 캐리 모형에서 평가도구를 교수전략·자료 개발과 연계하는 이유를 설명하시오.","answer":"수행목표에 대한 성취 증거를 먼저 구체화하여 교수전략과 자료가 목표 달성에 정렬되도록 하기 위해서다.","keywords":["수행목표","평가도구","교수전략","정렬"],"kind":"설명"}],"source":{"document":"교육학_261019_163033.pdf","page":9,"status":"필기 이미지 직접 판독·문맥 편집","note":"해당 쪽의 판독 가능한 내용을 서술형 학습용으로 편집했으며, 원문 전체 전사나 공식 정답은 아닙니다."}},{"id":"edu-048","area":"교육방법","title":"캐롤의 학교학습 모형","page":9,"summary":"캐롤의 학교학습 모형은 학습에 실제 사용한 시간과 필요한 시간의 관계로 학습 정도를 설명하며, 적성·교수 이해력·학습 지속력·학습 기회·교수의 질이라는 다섯 변인을 고려한다.","sections":[{"heading":"핵심 관계","text":"학습의 정도는 학습에 실제 사용한 시간과 학습에 필요한 시간의 비율에 영향을 받는다. 캐롤 모형의 다섯 변인은 적성, 교수 이해력, 학습 지속력, 학습 기회, 교수의 질이다. 적성·교수 이해력·교수의 질은 주로 필요한 시간과, 학습 지속력·학습 기회는 주로 사용한 시간과 관련된다."},{"heading":"시사점","text":"학습자에 따라 과제 숙달에 필요한 시간이 다를 수 있으므로 교수의 질과 학습자의 이해를 지원하고, 충분한 학습 기회 및 지속적인 참여가 가능하도록 수업을 조정한다. 적성을 고정된 성취 상한으로 단정하지 않는다."}],"questions":[{"id":"edu-048-q1","prompt":"캐롤의 학교학습 모형에서 학습 정도를 설명하는 핵심 시간 관계는?","answer":"학습에 사용한 시간과 학습에 필요한 시간의 비율이다.","keywords":["사용한 시간","필요한 시간"],"kind":"개념"}],"source":{"document":"교육학_261019_163033.pdf","page":9,"status":"필기 이미지 직접 판독·문맥 편집","note":"해당 쪽의 판독 가능한 내용을 서술형 학습용으로 편집했으며, 원문 전체 전사나 공식 정답은 아닙니다."}},{"id":"edu-049","area":"교육방법","title":"인지적 도제 교수법","page":12,"summary":"전문가의 사고 과정을 학습자가 관찰하고 참여하도록 지원하는 교수법이다.","sections":[{"heading":"핵심 개념","text":"전문가의 문제해결 사고를 드러내고 학습자가 점차 독립적으로 수행하게 돕는다."},{"heading":"원문에 제시된 교수 과정","text":"원문에서 제시한 대표적 전략은 모델링(시범), 코칭, 비계 설정, 명료화, 반성, 탐색이다. 이들은 교수설계에 활용할 수 있는 전략이며 모든 수업에서 반드시 고정된 순서로만 적용해야 한다는 의미는 아니다."}],"questions":[{"id":"edu-049-q1","prompt":"인지적 도제 교수법에서 활용하는 주요 교수 전략 여섯 가지를 제시하시오.","answer":"모델링(시범), 코칭, 비계 설정, 명료화, 반성, 탐색이다. 이는 교수·학습을 설계할 때 고려하는 전략들로, 모든 수업에서 반드시 고정된 순서대로 수행해야 한다는 뜻은 아니다.","keywords":["모델링","코칭","비계 설정","명료화","반성","탐색"],"kind":"절차"}],"source":{"document":"교육학_261019_163033.pdf","page":12,"status":"필기 이미지 직접 판독·문맥 편집","note":"해당 쪽의 판독 가능한 내용을 서술형 학습용으로 편집했으며, 원문 전체 전사나 공식 정답은 아닙니다."}},{"id":"edu-050","area":"교육방법","title":"정착수업(Anchored Instruction)","page":12,"summary":"실제적 맥락을 제공하는 사례나 이야기를 중심으로 학습 문제를 탐구한다.","sections":[{"heading":"핵심 특징","text":"실제와 유사한 상황·이야기 속에서 학습자가 필요한 정보를 활용하여 문제를 해결하도록 한다."},{"heading":"교수 설계","text":"학습자가 맥락 속 단서를 파악하고 탐구할 수 있도록 풍부한 문제 상황을 제시한다."}],"questions":[{"id":"edu-050-q1","prompt":"정착수업의 핵심 특징을 서술하시오.","answer":"실제와 유사한 맥락을 담은 사례나 이야기 속에 문제를 제시하고 학습자가 맥락 정보로 해결안을 탐색하게 한다.","keywords":["실제적 맥락","사례·이야기","문제 해결"],"kind":"개념"}],"source":{"document":"교육학_261019_163033.pdf","page":12,"status":"필기 이미지 직접 판독·문맥 편집","note":"해당 쪽의 판독 가능한 내용을 서술형 학습용으로 편집했으며, 원문 전체 전사나 공식 정답은 아닙니다."}},{"id":"edu-051","area":"교육방법","title":"교사의 발문과 탐구 촉진","page":12,"summary":"발문을 명료화·이유와 증거·관점 탐색으로 구분해 사고를 촉진한다.","sections":[{"heading":"명료화 질문","text":"학생의 뜻이나 설명을 더 구체적으로 밝혀 달라고 요청한다."},{"heading":"이유와 증거 질문","text":"주장에 대한 근거와 추론을 요청한다."},{"heading":"관점 질문","text":"다른 사람의 입장이나 반대 의견을 탐색하도록 한다."}],"questions":[{"id":"edu-051-q1","prompt":"학습자의 사고를 심화시키는 교사 발문의 예를 세 가지 제시하시오.","answer":"① 학생의 설명을 더 명확히 하도록 요청하는 발문(“그 말의 의미를 자세히 설명해 줄래?”). ② 주장을 뒷받침하는 근거를 요구하는 발문(“그렇게 생각한 이유는?”). ③ 다른 관점이나 대안을 탐색하게 하는 발문(“다른 해결 방법도 있을까?”). 특정한 공식 분류가 아니라 수업에 활용할 수 있는 예시다.","keywords":["명료화 발문","근거 탐색 발문","대안 탐색 발문"],"kind":"적용"}],"source":{"document":"교육학_261019_163033.pdf","page":12,"status":"필기 이미지 직접 판독·문맥 편집","note":"해당 쪽의 판독 가능한 내용을 서술형 학습용으로 편집했으며, 원문 전체 전사나 공식 정답은 아닙니다."}},{"id":"edu-052","area":"교육방법","title":"ASSURE 수업설계 모형","page":15,"summary":"매체 활용 중심의 수업설계 절차를 여섯 단계로 구분한다.","sections":[{"heading":"A","text":"학습자 특성 분석(Analyze learners)."},{"heading":"S","text":"수업목표 진술(State objectives)."},{"heading":"S","text":"교수 방법·매체·자료 선정(Select methods, media and materials)."},{"heading":"U","text":"매체·자료 활용(Utilize media and materials)."},{"heading":"R","text":"학습자 참여 요구(Require learner participation)."},{"heading":"E","text":"평가와 수정(Evaluate and revise)."}],"questions":[{"id":"edu-052-q1","prompt":"ASSURE 모형의 여섯 단계를 순서대로 설명하시오.","answer":"학습자 분석 → 학습목표 진술 → 교수방법·매체·자료 선정 → 매체·자료 활용 → 학습자 참여 요구 → 평가 및 수정이다.","keywords":["학습자 분석","목표 진술","교수방법·매체·자료 선정","매체·자료 활용","학습자 참여","평가·수정"],"kind":"절차"}],"source":{"document":"교육학_261019_163033.pdf","page":15,"status":"필기 이미지 직접 판독·문맥 편집","note":"해당 쪽의 판독 가능한 내용을 서술형 학습용으로 편집했으며, 원문 전체 전사나 공식 정답은 아닙니다."}},{"id":"edu-053","area":"교육평가","title":"선발적 교육관과 발달적 교육관","page":15,"summary":"평가를 선발에 활용하는 관점과 학습자의 성장 지원에 활용하는 관점을 구분한다.","sections":[{"heading":"선발적 교육관","text":"학습자의 상대적 수준을 비교·판단하고 선발하는 데 초점을 둔다."},{"heading":"발달적 교육관","text":"학습자에게 적절한 학습 기회를 제공하고 성장 정도를 진단·지원하는 데 중점을 둔다."}],"questions":[{"id":"edu-053-q1","prompt":"선발적 교육관과 발달적 교육관에서 평가의 역할을 비교하시오.","answer":"선발적 교육관은 비교와 선발을 중시하고, 발달적 교육관은 학습자의 진단·성장 및 교수·학습 개선을 중시한다.","keywords":["선발","진단","성장"],"kind":"비교"}],"source":{"document":"교육학_261019_163033.pdf","page":15,"status":"필기 이미지 직접 판독·문맥 편집","note":"해당 쪽의 판독 가능한 내용을 서술형 학습용으로 편집했으며, 원문 전체 전사나 공식 정답은 아닙니다."}},{"id":"edu-054","area":"교육평가","title":"규준참조평가와 준거참조평가","page":16,"summary":"집단 내 상대적 위치와 교육목표 도달 여부를 비교 기준으로 사용하는 평가를 구분한다.","sections":[{"heading":"규준참조평가","text":"비교집단의 성취에 비추어 개인의 상대적 위치를 판단한다."},{"heading":"준거참조평가","text":"사전에 정한 성취기준에 비추어 학습자의 목표 달성 정도를 판단한다."}],"questions":[{"id":"edu-054-q1","prompt":"동일한 시험 점수가 나왔을 때 규준참조평가와 준거참조평가는 결과를 어떻게 다르게 해석하는지 비교하시오.","answer":"규준참조평가는 해당 점수가 비교집단 안에서 어느 위치에 해당하는지를 해석한다. 준거참조평가는 사전에 정한 성취기준에 도달했는지를 해석한다. 따라서 같은 점수도 상대적 위치와 기준 충족이라는 서로 다른 판단으로 이어진다.","keywords":["규준: 집단 내 상대적 위치","준거: 성취기준 충족 여부"],"kind":"비교"}],"source":{"document":"교육학_261019_163033.pdf","page":16,"status":"필기 이미지 직접 판독·문맥 편집","note":"해당 쪽의 판독 가능한 내용을 서술형 학습용으로 편집했으며, 원문 전체 전사나 공식 정답은 아닙니다."}},{"id":"edu-055","area":"교육평가","title":"능력참조평가와 성장참조평가","page":16,"summary":"학습자의 개인 능력 또는 과거 수행에 비추어 결과를 해석하는 방식을 구분한다.","sections":[{"heading":"능력참조평가","text":"학습자 자신의 능력 수준과 비교하여 어느 정도 수행하였는지를 평가한다."},{"heading":"성장참조평가","text":"과거에 비해 얼마나 성장하거나 변화하였는지를 평가한다."}],"questions":[{"id":"edu-055-q1","prompt":"능력참조평가와 성장참조평가를 비교하시오.","answer":"능력참조평가는 개인의 능력 수준과 현재 성취를 비교하고, 성장참조평가는 이전의 자기 수행과 현재 성취를 비교하여 변화 정도를 본다.","keywords":["능력 수준","과거 수행","변화"],"kind":"비교"}],"source":{"document":"교육학_261019_163033.pdf","page":16,"status":"필기 이미지 직접 판독·문맥 편집","note":"해당 쪽의 판독 가능한 내용을 서술형 학습용으로 편집했으며, 원문 전체 전사나 공식 정답은 아닙니다."}},{"id":"edu-056","area":"교육평가","title":"형성평가의 목적과 활용","page":17,"summary":"수업 과정의 개선을 위해 학습자의 이해 상태에 대한 증거를 수집한다.","sections":[{"heading":"핵심 목적","text":"교육·학습 과정에서 학습자의 이해를 점검하고 교수·학습 전략을 수정하는 데 활용한다."},{"heading":"활용","text":"피드백을 제공하고 학습 내용을 보충하거나 교수 방법을 조정한다."}],"questions":[{"id":"edu-056-q1","prompt":"형성평가에서 다수 학생이 동일한 오개념을 보인 경우, 교사가 평가 결과를 활용할 행동을 두 가지 서술하시오.","answer":"① 오개념이 무엇인지 학생에게 구체적으로 피드백하고 수정할 기회를 제공한다. ② 해당 개념을 다시 설명하거나 다른 예시·활동을 마련해 다음 수업의 교수전략을 조정한다.","keywords":["오개념에 대한 구체적 피드백","재설명·활동 조정 등 교수 개선"],"kind":"개념"}],"source":{"document":"교육학_261019_163033.pdf","page":17,"status":"필기 이미지 직접 판독·문맥 편집","note":"해당 쪽의 판독 가능한 내용을 서술형 학습용으로 편집했으며, 원문 전체 전사나 공식 정답은 아닙니다."}},{"id":"edu-057","area":"교육평가","title":"자기평가와 동료평가","page":17,"summary":"평가 주체에 따른 자기평가와 동료평가의 목적·유의점을 구분한다.","sections":[{"heading":"자기평가","text":"학습자가 자신의 과정이나 결과를 기준에 따라 성찰하고 평가한다."},{"heading":"동료평가","text":"학습 구성원들이 서로의 수행을 관찰하고 근거에 따라 평가·피드백한다."},{"heading":"유의점","text":"평가기준을 명확히 하고 관계에 따른 편향을 줄이도록 한다."}],"questions":[{"id":"edu-057-q1","prompt":"자기평가의 교육적 장점과 유의점을 서술하시오.","answer":"자기 성찰과 자기조절을 촉진하나 평가 기준을 명확히 제시해 자의적 판단을 줄일 필요가 있다.","keywords":["자기 성찰","평가 기준"],"kind":"적용"},{"id":"edu-057-q2","prompt":"동료평가의 실시 시 유의할 점을 제시하시오.","answer":"구체적인 기준을 공유하고 친분·편견에 따른 평가를 줄이며, 근거에 기초한 피드백을 제공하도록 한다.","keywords":["평가기준","편향","피드백"],"kind":"적용"}],"source":{"document":"교육학_261019_163033.pdf","page":17,"status":"필기 이미지 직접 판독·문맥 편집","note":"해당 쪽의 판독 가능한 내용을 서술형 학습용으로 편집했으며, 원문 전체 전사나 공식 정답은 아닙니다."}},{"id":"edu-058","area":"교육행정","title":"학교운영위원회 구성과 위원 정수","page":23,"summary":"학교운영위원회는 학부모위원·교원위원·지역위원으로 구성한다. 위원 정수와 구성비율은 학생 수, 학교 유형 및 예외 규정에 따라 구분한다.","sections":[{"heading":"구성 집단","text":"학부모위원·교원위원·지역위원으로 구성한다. 학교운영위원회규정으로 구체적 정수·구성비율을 정한다."},{"heading":"위원 정수(학생 수 기준)","text":"국·공립학교의 학생 수가 200명 미만이면 5~8명, 200명 이상 1,000명 미만이면 9~12명, 1,000명 이상이면 13~15명이다(초·중등교육법 시행령 제58조 제1항)."},{"heading":"일반학교 구성비율","text":"국·공립 일반학교의 학부모위원 40~50%, 교원위원 30~40%, 지역위원 10~30%이다(같은 조 제2항)."},{"heading":"산업수요 맞춤형고·특성화고","text":"해당 고등학교에서는 학부모위원 30~40%, 교원위원 20~30%, 지역위원 30~50%로 정할 수 있다(같은 조 제3항)."},{"heading":"예외와 확인","text":"학생 수 100명 미만의 초·중·고·특수학교 등은 정해진 범위에서 구성비율을 달리 정할 수 있으며 세 집단이 각각 1명 이상 포함되어야 한다. 사립학교에도 제58조 등을 준용하되 별도 규정이 적용된다. 실제 적용 시 국가법령정보센터의 현행 조문과 해당 학교 규정을 확인한다."}],"questions":[{"id":"edu-058-q1","prompt":"국·공립학교의 학교운영위원회 구성 집단 세 가지와 학생 수에 따른 위원 정수 구분을 서술하시오(일반적 기준).","answer":"국·공립학교 학교운영위원회는 학부모위원·교원위원·지역위원으로 구성된다. 위원 정수의 일반적 기준은 학생 수 200명 미만 5~8명, 200명 이상 1,000명 미만 9~12명, 1,000명 이상 13~15명이다. 실제 구성은 학교 유형·예외 규정과 학교운영위원회규정을 함께 확인한다.","keywords":["학부모위원·교원위원·지역위원","학생 수에 따른 정수 구분","5~8명 / 9~12명 / 13~15명"],"kind":"개념"}],"source":{"document":"교육학_261019_163033.pdf","page":23,"status":"기존 필기 메모 주제 + 현행 법령 확인 후 내용 수정","note":"필기 메모에서 주제를 복원했으며, 위원 정수·구성비율은 2026-11-10 기준 국가법령정보센터 「초·중등교육법 시행령」 제58조 및 제63조로 별도 검증·보완한 내용입니다. 최신 개정 여부를 재확인하세요.","lawUrl":"https://www.law.go.kr/lsLinkCommonInfo.do?chrClsCd=010202&lspttninfSeq=82359"}},{"id":"edu-059","area":"협동학습","title":"TGT 팀게임토너먼트","page":14,"summary":"TGT는 팀 학습 후 학업 성취 수준이 비슷한 학생끼리 게임·토너먼트에 참여하여 팀의 성과에 기여하는 협동학습 모형이다.","sections":[{"heading":"핵심 구성","text":"이질적인 팀에서 서로 가르치고 연습한 다음, 유사한 성취 수준의 학생들이 게임·토너먼트에서 경쟁하도록 구성한다. 게임 점수는 팀 점수 또는 팀 인정·보상에 반영한다."},{"heading":"STAD와의 구별","text":"STAD는 일반적으로 개인 퀴즈와 개인 향상 점수를 팀 성과에 반영하며, TGT는 게임·토너먼트를 활용한다. 구체적인 운영 방식은 자료와 적용 맥락에 따라 다를 수 있다."}],"questions":[{"id":"edu-059-q1","prompt":"TGT와 STAD의 학습 성과 확인 방식에서 대표적인 차이를 설명하시오.","answer":"TGT는 팀 학습 후 성취 수준이 유사한 학생끼리 게임·토너먼트에 참여하여 얻은 점수를 팀 성과에 반영한다. STAD는 팀 학습 후 개인 퀴즈와 이전 성취 대비 향상 점수를 팀 성과에 반영하는 것이 대표적이다.","keywords":["TGT: 게임·토너먼트","STAD: 개인 퀴즈·향상 점수","팀 성과와 연결"],"kind":"비교"},{"id":"edu-059-q2","prompt":"TGT에서 학생들이 토너먼트에 참여하기 전에 수행하는 대표적인 학습 활동을 쓰시오.","answer":"이질적인 팀에서 내용 이해를 돕고 서로 설명하며 게임·토너먼트를 준비하는 팀 학습 활동을 한다.","keywords":["이질적 팀 구성","상호 설명과 팀 학습"],"kind":"개념"}],"source":{"document":"교육학_261019_163033.pdf","page":14,"status":"필기 원문에서 주제 확인 + 외부 문헌으로 개념·문항 보완","note":"원문 14쪽에는 TGT의 명칭이 짧게 제시됩니다. 운영 설명과 문제는 DeVries·Slavin 등의 외부 자료를 참고한 편집 내용이며 필기 문장의 직접 전사가 아닙니다."}},{"id":"edu-060","area":"협동학습","title":"LT 함께학습하기(Learning Together)","page":14,"summary":"LT는 소집단이 공동 과제를 협력적으로 수행하면서 긍정적 상호의존과 개별적 책무성 등을 촉진하는 협동학습 접근이다.","sections":[{"heading":"협동학습의 구성 요소","text":"긍정적 상호의존, 개별적 책무성, 촉진적 상호작용, 사회적 기술, 집단 과정(집단 기능에 대한 성찰)을 함께 고려한다."},{"heading":"수업 설계","text":"공동 목표와 구성원의 기여를 명확히 하고, 팀이 함께 과제를 수행하게 하며, 상호 도움과 집단 과정 점검을 지원한다. 단순히 한 조로 앉히는 것만으로 협동학습이 성립하지는 않는다."}],"questions":[{"id":"edu-060-q1","prompt":"LT 등 협동학습을 단순한 모둠활동과 구별하는 핵심 요소 세 가지를 쓰시오.","answer":"긍정적 상호의존, 개별적 책무성, 촉진적 상호작용을 들 수 있다. 사회적 기술과 집단 과정 또한 중요하다.","keywords":["긍정적 상호의존","개별적 책무성","촉진적 상호작용"],"kind":"개념"},{"id":"edu-060-q2","prompt":"LT 방식으로 공동 과제를 제시할 때 교사가 집단 과정을 지원하는 방안 한 가지를 서술하시오.","answer":"활동 후 모둠 구성원들이 협력 과정에서 잘한 점과 개선할 점을 되돌아보고 다음 활동의 개선 방안을 합의하도록 한다.","keywords":["집단 과정에 대한 성찰과 개선 방안 합의"],"kind":"적용"}],"source":{"document":"교육학_261019_163033.pdf","page":14,"status":"필기 원문에서 주제 확인 + 외부 문헌으로 개념·문항 보완","note":"원문 14쪽에는 LT 명칭만 제시됩니다. 세부 구성 요소와 질문은 Johnson·Johnson의 협동학습 자료를 참고해 보완했습니다."}},{"id":"edu-061","area":"협동학습","title":"GI 집단탐구(Group Investigation)","page":14,"summary":"GI는 학생들이 하위 주제를 정하고 협력적으로 탐구를 계획·수행한 뒤 결과를 발표·평가하는 학생 주도 협동학습 모형이다.","sections":[{"heading":"대표적 과정","text":"주제·소주제 선택과 집단 조직 → 탐구 계획 → 조사·탐구 수행 → 결과 분석과 발표 준비 → 발표 → 평가로 정리할 수 있다."},{"heading":"학습자와 교사의 역할","text":"학생은 탐구할 문제와 방법을 협의하고 정보 수집·분석·발표에 참여한다. 교사는 자료와 탐구를 지원하고 집단 운영을 조정한다. 과정은 수업 맥락에서 유연하게 조정한다."}],"questions":[{"id":"edu-061-q1","prompt":"GI 집단탐구의 대표적인 과정을 탐구 계획부터 평가까지 설명하시오.","answer":"모둠이 탐구 주제와 수행 계획을 협의하고 조사·탐구를 수행한다. 결과를 분석하여 발표한 뒤 개인·집단의 학습과 수행 과정을 평가한다.","keywords":["탐구 계획","조사·분석","발표","평가"],"kind":"절차"},{"id":"edu-061-q2","prompt":"GI 수업에서 학생의 탐구 자율성을 유지하면서 교사가 수행할 지원 행동 두 가지를 제시하시오.","answer":"① 자료 탐색이나 조사 방법을 안내하고 필요한 자원을 제공한다. ② 모둠별 탐구 진행과 참여를 점검하며 협의·발표 과정에 피드백을 제공한다.","keywords":["자료·방법 지원","집단 진행 점검·피드백"],"kind":"적용"}],"source":{"document":"교육학_261019_163033.pdf","page":14,"status":"필기 원문에서 주제 확인 + 외부 문헌으로 개념·문항 보완","note":"원문 14쪽에는 GI 명칭만 제시됩니다. 단계 및 역할 설명은 Sharan의 집단탐구 관련 자료를 참고한 외부 보완입니다."}},{"id":"edu-062","area":"교육공학","title":"데일의 경험의 원추","page":14,"summary":"데일의 경험의 원추는 교육적 경험과 매체의 구체성·추상성 정도를 비교하는 개념적 도식이다. 기억률을 수치로 예측하는 도구가 아니다.","sections":[{"heading":"주요 취지","text":"직접·목적적 경험, 구성된 경험, 시범, 영상·그림·언어 기호 등 경험과 표현의 상대적 구체성·추상성을 보여 주는 도식이다. 원본 필기 14쪽에도 원추 도식이 제시된다."},{"heading":"해석상의 주의","text":"원추의 아래쪽 활동이 언제나 위쪽 활동보다 학습 효과가 높다는 뜻은 아니다. 읽기 10%, 듣기 20%, 직접 하기 90% 등의 기억률 수치는 데일의 원래 원추에 포함되지 않으며 이를 뒷받침하는 근거도 없다."},{"heading":"수업 적용","text":"수업 목표, 학습자 수준, 과제 특성에 따라 구체적 경험과 상징적 표현을 적절히 결합한다."}],"questions":[{"id":"edu-062-q1","prompt":"데일의 경험의 원추가 주로 구분하는 경험의 특성과, 이 모형의 해석상 주의점 한 가지를 쓰시오.","answer":"이 모형은 경험과 교수 매체의 구체성·추상성 정도를 비교한다. 원추의 위치가 학습 성과의 우열이나 고정된 기억률을 의미하는 것은 아니다.","keywords":["구체성·추상성","기억률·효과 우열로 단정 금지"],"kind":"개념"},{"id":"edu-062-q2","prompt":"학생에게 그래프 해석을 가르칠 때 데일의 경험의 원추를 참고해 구체적 활동과 추상적 표현을 연결하는 방안을 제안하시오.","answer":"실제 자료를 조사·측정하거나 표로 정리하는 활동과 그래프의 축·기호·언어적 설명을 연결한다. 도식은 매체 선택의 참고일 뿐 학습 효과의 고정 서열을 뜻하지 않는다.","keywords":["구체적 자료 활동","그래프 기호·설명 연결","매체 선택 맥락화"],"kind":"적용"}],"source":{"document":"교육학_261019_163033.pdf","page":14,"status":"필기 원문에서 주제 확인 + 외부 문헌으로 개념·문항 보완","note":"원문 14쪽의 원추 도식은 직접 확인했습니다. 원추에 대한 과잉 해석과 허위 기억률 수치는 Molenda 등 문헌에 근거해 별도로 보정했습니다."}},{"id":"edu-063","area":"교육평가","title":"평정에서 발생할 수 있는 오류","page":18,"summary":"평정 과정에서 평가자의 인상·기준·판단 경향 때문에 평가 결과가 왜곡될 수 있다.","sections":[{"heading":"대표적 오류","text":"논리적 오류, 평정 경향의 오류, 대비의 오류, 후광 효과, 관대화 오류, 근접의 오류 등이 필기에 열거되어 있다."},{"heading":"유의할 점","text":"같은 수행에 대해 평가자에 따라 판단이 달라질 수 있다. 평가 기준과 증거를 분명히 하고 구체적인 관찰 기록을 활용하여 오류를 줄여야 한다."}],"questions":[{"id":"edu-063-q1","prompt":"후광 효과와 관대화 오류를 구별하여 설명하시오.","answer":"후광 효과는 특정 특성에 대한 전반적 인상이 다른 평가 차원의 판단에 영향을 주는 오류이다. 관대화 오류는 평가자가 대체로 점수를 후하게 주는 경향이다.","keywords":["후광 효과: 한 인상의 영향","관대화: 전반적으로 후한 평정"],"kind":"비교"},{"id":"edu-063-q2","prompt":"수행평가에서 평정 오류를 줄이기 위한 실천 방안 두 가지를 제시하시오.","answer":"① 관찰 가능한 수행 지표가 포함된 루브릭을 사용한다. ② 한 번의 인상만으로 판단하지 않고 수행 증거를 여러 시점에서 기록한다.","keywords":["구체적 평가 기준","다양한 수행 증거"],"kind":"적용"}],"source":{"document":"교육학_261019_163033.pdf","page":18,"status":"필기 원문 해당 쪽에서 주제 확인 + 학습용 재서술","note":"원문 18쪽의 평정 오류 목록을 확인했다. 정의·예방 방안은 임용 학습용으로 재서술했으며 원문 문장을 그대로 옮긴 것은 아니다."}},{"id":"edu-064","area":"교육행정","title":"학교 조직풍토와 OCDQ-RE","page":21,"summary":"학교 조직풍토는 구성원이 지각하는 학교 조직의 상호작용과 행동 특성으로, 교장·교사 행동을 함께 고려할 수 있다.","sections":[{"heading":"조직풍토 관찰의 관점","text":"필기에는 교장·교사의 개방성과 폐쇄성에 따른 조직풍토 구분, OCDQ-RE가 제시된다."},{"heading":"행동 차원","text":"교장 행동에는 지원·지시·제한과 같은 차원, 교사 행동에는 전문적·친교적·방관적 행동의 차원이 구분되어 있다. 차원 명칭과 점수 해석은 검사 도구에 따라 확인할 필요가 있다."}],"questions":[{"id":"edu-064-q1","prompt":"학교 조직풍토를 교장의 행동만으로 판단하기 어려운 이유를 설명하시오.","answer":"조직풍토에는 교장 행동뿐 아니라 교사들의 전문적 협력, 친교적 관계, 방관적 행동 등 구성원 사이의 상호작용도 반영되기 때문이다.","keywords":["교장 행동","교사 행동","상호작용"],"kind":"개념"},{"id":"edu-064-q2","prompt":"OCDQ-RE에서 교장의 지원적 행동과 지시적 행동을 구별하여 설명하시오.","answer":"지원적 행동은 교사의 전문적 활동을 격려·지원하는 행동이고, 지시적 행동은 교사가 수행하는 업무를 세세하게 통제·지시하는 경향이다.","keywords":["지원·격려","세세한 지시·통제"],"kind":"비교"}],"source":{"document":"교육학_261019_163033.pdf","page":21,"status":"필기 원문 해당 쪽에서 주제 확인 + 학습용 재서술","note":"원문 21쪽의 조직풍토와 OCDQ-RE, 교장 및 교사의 행동 차원을 확인했다. 척도 점수 계산이나 정확한 유형 판정 공식은 원문만으로 확정하지 않는다."}},{"id":"edu-065","area":"교육행정","title":"학교 조직문화의 유형","page":21,"summary":"필기에는 가족문화·기계문화·공연문화·공포문화와 같은 학교문화 유형을 대비해 정리해 두었다.","sections":[{"heading":"주요 구분","text":"가족문화는 구성원 사이의 신뢰·협력 관계를 강조한다. 기계문화는 구성원들이 개별적으로 행동하고 조직의 협력이 제한되는 양상을 설명한다."},{"heading":"유의점","text":"이 유형들은 학교 분위기를 이해하는 학습용 분류로, 모든 학교가 항상 하나의 유형으로 고정되는 것은 아니다. 이 명칭만으로 특정 학교의 교육성과를 단정할 수 없다."}],"questions":[{"id":"edu-065-q1","prompt":"가족문화와 기계문화로 묘사되는 학교 조직의 차이를 설명하시오.","answer":"가족문화는 구성원의 친밀한 관계와 상호 지원을 강조하는 반면, 기계문화는 개별적 활동과 형식적·제한적인 상호작용을 중심으로 묘사한다.","keywords":["가족: 신뢰·협력","기계: 개별 활동·제한적 상호작용"],"kind":"비교"},{"id":"edu-065-q2","prompt":"학교 조직문화를 하나의 유형명만으로 단정할 때의 한계를 서술하시오.","answer":"한 학교에서도 관계·업무·시기별로 서로 다른 문화적 특성이 나타날 수 있으므로 실제 관찰과 구성원 경험을 함께 검토해야 한다.","keywords":["유형의 단순화 경계","관찰·경험 근거"],"kind":"적용"}],"source":{"document":"교육학_261019_163033.pdf","page":21,"status":"필기 원문 해당 쪽에서 주제 확인 + 학습용 재서술","note":"원문 21쪽에서 가족·기계·공연·공포문화 명칭을 확인했다. 특정 연구자의 공식 분류 체계나 유형별 효과를 확정하는 자료로 취급하지 않는다."}},{"id":"edu-066","area":"교육행정","title":"합리적 의사결정 모형과 점증모형","page":22,"summary":"합리적 의사결정은 대안을 포괄적으로 탐색·비교하려는 접근이고, 점증모형은 기존 정책을 기초로 작은 변경을 반복하는 접근이다.","sections":[{"heading":"합리적 모형","text":"문제를 명확히 정의하고 대안과 결과를 비교해 목표에 적합한 대안을 선택하려 한다. 정보·시간·분석 능력 제약 때문에 실제 완전한 합리성을 구현하기 어렵다."},{"heading":"점증모형","text":"현실의 제약 속에서 기존 정책·관행을 출발점으로 비교적 작은 변화를 누적한다. 실행 가능성은 높일 수 있지만 구조적 문제 해결은 제한될 수 있다."}],"questions":[{"id":"edu-066-q1","prompt":"합리적 의사결정 모형과 점증모형의 대안 탐색 방식을 비교하시오.","answer":"합리적 모형은 가능한 대안과 예상 결과를 폭넓게 분석·비교하려 하고, 점증모형은 기존 정책을 바탕으로 상대적으로 작은 수정 대안을 우선 검토한다.","keywords":["합리적: 포괄적 비교","점증: 기존 정책의 소폭 수정"],"kind":"비교"},{"id":"edu-066-q2","prompt":"학교의 시간표 개편에 점증모형을 적용하는 사례와 한계를 각각 한 가지 제시하시오.","answer":"기존 시간표를 유지하면서 특정 학년의 수업 배치만 시범 조정하는 것이 사례다. 다만 학교 전체의 구조적 시간 운영 문제를 해결하기에는 제한될 수 있다.","keywords":["소규모 시범 변경","구조적 문제 해결의 한계"],"kind":"적용"}],"source":{"document":"교육학_261019_163033.pdf","page":22,"status":"필기 원문 해당 쪽에서 주제 확인 + 학습용 재서술","note":"원문 22쪽의 합리적 의사결정 모형·점증모형 항목에서 특징을 확인했다. 예시는 새로 작성했다."}},{"id":"edu-067","area":"교육행정","title":"쓰레기통 의사결정 모형","page":22,"summary":"쓰레기통 모형은 목표가 모호하고 참여가 유동적인 조직에서 문제·해결책·참여자·선택 기회가 결합하며 의사결정이 이루어질 수 있음을 설명한다.","sections":[{"heading":"핵심 요소","text":"문제, 해결책, 참여자, 선택 기회라는 서로 다른 흐름이 특정 시점에 만난다는 데 주목한다."},{"heading":"적용 조건","text":"목표와 선호가 불분명하고 참여자가 유동적인 상황의 의사결정을 이해할 때 유용하다. 반드시 최선의 대안을 선택한다는 규범적 절차가 아니다."}],"questions":[{"id":"edu-067-q1","prompt":"쓰레기통 의사결정 모형의 네 가지 흐름을 쓰시오.","answer":"문제, 해결책, 참여자, 선택 기회(선택 상황)이다.","keywords":["문제","해결책","참여자","선택 기회"],"kind":"개념"},{"id":"edu-067-q2","prompt":"쓰레기통 모형이 합리적 의사결정 모형과 다른 점을 설명하시오.","answer":"합리적 모형은 문제를 명확히 하고 대안을 체계적으로 평가하려는 접근인 반면, 쓰레기통 모형은 목표가 모호하고 참여가 유동적인 조직에서 여러 흐름의 우연적 결합으로 결정이 성립할 수 있음을 설명한다.","keywords":["체계적 대안 평가","유동적인 흐름의 결합"],"kind":"비교"}],"source":{"document":"교육학_261019_163033.pdf","page":22,"status":"필기 원문 해당 쪽에서 주제 확인 + 학습용 재서술","note":"원문 22쪽에 쓰레기통 모형의 네 요소와 모호한 의사결정 상황을 확인했다. 설명은 이해를 돕기 위해 재서술했다."}},{"id":"edu-068","area":"교육행정","title":"장학의 여러 유형","page":22,"summary":"장학은 교수·학습의 개선을 지원하며, 주체와 수행 방식에 따라 임상장학 외에도 자기장학·동료장학·약식장학·컨설팅장학 등으로 정리할 수 있다.","sections":[{"heading":"자기장학과 동료장학","text":"자기장학은 교사가 자신의 수업을 계획적으로 점검·성찰하며 개선하는 방식이다. 동료장학은 교사들이 서로 수업을 관찰·협의·지원하는 방식이다."},{"heading":"약식장학과 컨설팅장학","text":"약식장학은 짧은 수업 관찰 등을 통해 개선에 필요한 피드백을 제공하는 방식이다. 컨설팅장학은 현장의 문제 해결을 위해 요청과 지원을 연결하는 접근이다."},{"heading":"임상장학과의 관계","text":"기존 개념의 임상장학은 수업 전 협의·관찰·분석·사후 협의를 중심으로 정리돼 있다. 장학 유형의 구분은 실행 맥락에 따라 일부 중첩될 수 있다."}],"questions":[{"id":"edu-068-q1","prompt":"자기장학과 동료장학의 차이를 교사의 활동 중심으로 서술하시오.","answer":"자기장학은 교사가 스스로 자신의 수업을 점검하고 개선하는 활동이고, 동료장학은 교사들이 상호 수업 관찰·협의·피드백으로 전문성을 높이는 활동이다.","keywords":["자기: 자기 점검·성찰","동료: 상호 관찰·협의"],"kind":"비교"},{"id":"edu-068-q2","prompt":"교사가 수업의 특정 문제 해결을 위해 외부 전문가의 지원을 요청한다면 어떤 장학 접근을 고려할 수 있으며 그 이유는 무엇인가?","answer":"컨설팅장학을 고려할 수 있다. 현장의 요청에 따라 문제를 진단하고 개선 대안을 함께 탐색하도록 전문적 지원을 제공하는 데 초점을 두기 때문이다.","keywords":["컨설팅장학","요청 기반 문제 해결·지원"],"kind":"적용"}],"source":{"document":"교육학_261019_163033.pdf","page":22,"status":"필기 원문 해당 쪽에서 주제 확인 + 학습용 재서술","note":"원문 22쪽의 임상·자기·동료·약식·컨설팅장학을 확인했다. 각 장학의 설명과 예시는 학습 목적에 맞게 재서술했다."}},{"id":"edu-069","area":"교육평가","title":"평가의 객관도","page":19,"summary":"객관도는 동일한 수행이나 답안을 평가할 때 평가자에 따라 결과가 얼마나 일관되게 나타나는지와 관련된다.","sections":[{"heading":"개념","text":"필기 19쪽에서는 객관도를 평가자가 달라도 검사·채점 결과가 유사하게 나타나는 정도와 연결한다. 객관도는 평가자 간 일치 또는 평가자에 의한 영향에 초점을 둔다."},{"heading":"객관도를 높이는 방안","text":"채점 기준과 수행 수준을 명료하게 제시하고, 채점자 사전 협의·훈련, 여러 평가자 채점 및 불일치 조정 등을 활용할 수 있다."},{"heading":"신뢰도와 구분","text":"객관도는 평가자에 따른 일관성에 특히 초점을 두며, 신뢰도는 더 넓은 측정의 일관성·오차 문제를 다룬다. 객관도는 신뢰도 논의와 관련되지만 모든 신뢰도와 동일한 말은 아니다."}],"questions":[{"id":"edu-069-q1","prompt":"교육평가에서 객관도가 의미하는 바를 평가자와 연결하여 서술하시오.","answer":"동일한 학생의 답안이나 수행에 대해 채점자·평가자가 달라져도 평가 결과가 일관되게 나타나는 정도를 의미한다.","keywords":["동일한 수행·답안","평가자 차이","일관성"],"kind":"개념"},{"id":"edu-069-q2","prompt":"서술형 수행평가에서 채점의 객관도를 높이기 위한 방안 두 가지를 제시하시오.","answer":"① 관찰 가능한 수행 수준이 구분된 명료한 채점 기준(분석적 루브릭 등)을 마련한다. ② 채점자들이 예시 답안을 함께 채점하여 기준을 조정하거나 복수 채점 후 불일치를 검토한다.","keywords":["명료한 채점 기준","채점자 협의·복수 채점"],"kind":"적용"}],"source":{"document":"교육학_261019_163033.pdf","page":19,"status":"필기 해당 쪽에서 개념 확인 + 학습용 재서술","note":"필기 19쪽에서 객관도의 정의를 확인했다. 채점 방법과 신뢰도와의 비교 설명은 일반적 측정 원리에 따라 학습용으로 정리했으며 원문 직접 인용이 아니다."}},{"id":"edu-070","area":"교육평가","title":"컴퓨터 적응검사(CAT)","page":19,"summary":"컴퓨터 적응검사는 앞선 응답을 이용해 이후 문항을 조정하여 응시자의 능력 수준을 효율적으로 추정하려는 검사 방식이다.","sections":[{"heading":"핵심 원리","text":"응시자의 초기 응답을 바탕으로 능력 수준을 추정하고, 문항은행에서 정보가 적절한 다음 문항을 선택한다. 응답에 따라 추정과 문항 선택을 반복하므로 응시자별 문항이 달라질 수 있다."},{"heading":"장점","text":"적절한 문항을 제시해 검사 효율성을 높이고, 설계와 문항은행의 질이 확보되면 필요한 측정 정밀도를 비교적 적은 문항으로 달성할 수 있다."},{"heading":"제약과 주의","text":"충분히 검증된 문항은행, 문항 매개변수 추정, 노출·보안 관리 등이 필요하다. 적응검사라고 해서 항상 더 정확하거나 공정하다고 단정할 수 없으며 응시자의 문항별 경험이 다를 수 있다."}],"questions":[{"id":"edu-070-q1","prompt":"컴퓨터 적응검사(CAT)가 다음 문항을 선택하는 기본 원리를 설명하시오.","answer":"이전 문항에 대한 응답을 이용해 응시자의 능력 수준을 추정하고, 그 추정값에서 측정 정보가 적절한 문항을 다음 문항으로 선택하는 과정을 반복한다.","keywords":["이전 응답","능력 추정","다음 문항 선택"],"kind":"설명"},{"id":"edu-070-q2","prompt":"컴퓨터 적응검사(CAT)의 기대 효과 한 가지와 시행상 유의점 한 가지를 설명하시오.","answer":"기대 효과: 능력 수준에 적절한 문항을 제시하여 검사 효율을 높일 수 있다. 유의점: 충분한 문항은행과 문항 특성의 검증, 보안 및 문항 노출 관리가 필요하다.","keywords":["효율적인 수준별 문항 제시","문항은행·검증 또는 보안 관리"],"kind":"비교"}],"source":{"document":"교육학_261019_163033.pdf","page":19,"status":"필기 해당 쪽에서 개념 확인 + 학습용 재서술","note":"필기 19쪽에는 CAT의 개념·장단점이 제시된다. 문항 선택 원리 및 기술적 제약은 학습을 위해 확장한 설명으로 원문 직접 인용이 아니다."}},{"id":"edu-071","area":"교육과정","title":"아이즈너의 예술적 교육과정 개발 모형","page":7,"summary":"교육과정 개발에서 질적 판단, 교육적 감식안과 교육비평의 중요성을 이해한다.","sections":[{"heading":"교육과정 개발 관점","text":"교육과정을 사전에 완전히 확정된 기술적 절차만으로 보기보다 교육적 상황의 질적 특성과 교사의 전문적 판단을 고려한다."},{"heading":"교육적 감식안과 교육비평","text":"교육적 감식안은 교육 상황에서 의미 있는 질적 특성과 미묘한 차이를 알아차리는 전문적 안목이다. 교육비평은 그러한 관찰과 판단을 타인이 이해할 수 있도록 기술·해석·평가하여 소통하는 활동이다."},{"heading":"원문 근거","text":"필기 7쪽에는 표현적 결과, 영 교육과정, 교육적 감식안, 교육비평이 함께 정리되어 있다. 본 문항은 그중 감식안과 비평의 구별에 집중한다."}],"questions":[{"id":"edu-071-q1","prompt":"아이즈너가 말한 교육적 감식안과 교육비평을 각각 설명하시오.","answer":"교육적 감식안은 교육 상황의 질적 특성을 분별하는 전문적 안목이고, 교육비평은 그 특성과 의미를 기술·해석·평가하여 다른 사람에게 드러내고 소통하는 활동이다.","keywords":["감식안: 질적 특성을 분별","비평: 기술·해석·평가 및 소통"],"kind":"비교"},{"id":"edu-071-q2","prompt":"교육목표를 미리 정한 행동 변화로만 한정할 때 아이즈너가 제기하는 문제의식을 설명하시오.","answer":"교육 경험에서는 미리 규정하지 못한 의미 있는 학습 결과가 나타날 수 있으므로, 모든 성과를 사전에 정해진 행동 목표로만 평가해서는 교육적 질과 예기치 않은 성장을 놓칠 수 있다.","keywords":["사전 행동목표의 한계","예상하지 못한 성과","질적 판단"],"kind":"설명"}],"source":{"document":"교육학_261019_163033.pdf","page":7,"status":"필기 7쪽 표제·특징 확인 + 학습용 재서술","note":"필기에서 개념명과 핵심 특징을 확인하였으며, 학습용 문항 및 답안은 새로 작성했습니다. 공식 기출 발문·채점기준이 아닙니다."}},{"id":"edu-072","area":"교육과정","title":"교과중심 교육과정","page":7,"summary":"교과 지식의 체계적 전달을 중시하는 교육과정의 특징·장단점을 이해한다.","sections":[{"heading":"주요 특징","text":"교과의 지식 체계와 학문적 내용을 중심으로 교육내용을 선정·조직하며, 교사가 교과 내용을 체계적으로 가르치는 역할이 강조된다."},{"heading":"장점과 한계","text":"내용의 체계적 조직과 전달, 교육내용의 계획·평가에 유리할 수 있다. 그러나 학습자의 경험·흥미나 실제 생활과의 관련성을 충분히 반영하지 못하거나 수동적 학습이 나타날 위험이 있다."},{"heading":"구분 유의","text":"교과중심은 교과 내용의 체계적 전달을 강조하는 전통적 유형이다. 학문의 핵심 개념·탐구 구조를 강조하는 학문중심 교육과정과 이름이 비슷하지만 동일한 개념은 아니다."}],"questions":[{"id":"edu-072-q1","prompt":"교과중심 교육과정의 대표적인 특징 두 가지를 제시하시오.","answer":"① 교과의 지식 체계를 중심으로 내용을 선정·조직한다. ② 교사가 교과 내용을 체계적으로 전달하는 활동을 중시한다.","keywords":["교과 지식 체계","교사의 체계적 전달"],"kind":"개념"},{"id":"edu-072-q2","prompt":"교과중심 교육과정의 장점 한 가지와 한계 한 가지를 설명하시오.","answer":"장점: 지식을 체계적으로 조직·전달하기 쉽다. 한계: 학습자의 관심·경험이나 생활과의 연계를 충분히 반영하지 못할 수 있다.","keywords":["장점: 체계적 조직·전달","한계: 학습자 경험·흥미 반영 부족"],"kind":"비교"}],"source":{"document":"교육학_261019_163033.pdf","page":7,"status":"필기 7쪽 표제·특징 확인 + 학습용 재서술","note":"필기에서 개념명과 핵심 특징을 확인하였으며, 학습용 문항 및 답안은 새로 작성했습니다. 공식 기출 발문·채점기준이 아닙니다."}},{"id":"edu-073","area":"교육과정","title":"경험중심 교육과정","page":7,"summary":"학습자의 흥미·요구와 직접 경험을 중심으로 교육과정을 조직하는 관점을 이해한다.","sections":[{"heading":"주요 특징","text":"학습자의 흥미와 요구, 생활 경험을 중요한 출발점으로 삼고 학습자의 능동적 활동과 문제해결을 강조한다."},{"heading":"장점과 한계","text":"학습자 중심의 참여와 실제 생활 연계에 유리할 수 있다. 반면 교육내용의 체계성·계열성을 확보하기 어렵거나 학습자의 흥미에 지나치게 의존할 위험이 있다."},{"heading":"유형 관련 메모","text":"필기 7쪽은 경험중심 교육과정의 조직 유형으로 활동형·중핵형·생성형을 적고 있다. 유형의 세부 정의는 이 항목에서 단정하지 않고 대표 특징과 장단점을 우선 학습한다."}],"questions":[{"id":"edu-073-q1","prompt":"경험중심 교육과정에서 교육내용을 조직할 때 중시하는 기준 두 가지를 쓰시오.","answer":"학습자의 흥미·요구와 실제 생활에서의 경험을 중시한다.","keywords":["학습자 흥미·요구","실제 생활 경험"],"kind":"개념"},{"id":"edu-073-q2","prompt":"경험중심 교육과정과 교과중심 교육과정의 교육내용 조직 원리를 비교하시오.","answer":"경험중심 교육과정은 학습자의 흥미·요구와 생활 경험을 중심으로 내용을 구성한다. 반면 교과중심 교육과정은 교과 지식의 논리적 체계와 전달을 중심으로 내용을 구성한다.","keywords":["경험중심: 흥미·생활경험","교과중심: 지식 체계·전달"],"kind":"비교"}],"source":{"document":"교육학_261019_163033.pdf","page":7,"status":"필기 7쪽 표제·특징 확인 + 학습용 재서술","note":"필기에서 개념명과 핵심 특징을 확인하였으며, 학습용 문항 및 답안은 새로 작성했습니다. 공식 기출 발문·채점기준이 아닙니다."}},{"id":"edu-074","area":"교육방법","title":"발견학습","page":11,"summary":"교사가 자료와 탐구 환경을 제공하고 학습자가 개념·규칙을 찾아가도록 돕는 교수법이다.","sections":[{"heading":"교사의 역할","text":"탐구할 문제와 적절한 자료를 제공하고, 학생이 탐색할 수 있도록 지도·도움·교정·피드백을 제공한다. 학생의 사고를 대신하는 것이 아니라 탐구 과정을 지원한다."},{"heading":"학습상의 특징","text":"학습자는 제공된 사례나 자료를 탐색하면서 개념·원리를 구성한다. 교사는 학습자의 선수지식과 과제 수준에 맞는 구조화를 제공해야 한다."},{"heading":"장단점","text":"탐구 과정에서 자기주도성과 사고를 발달시킬 기회가 있으나 시간과 교사의 준비 부담이 커질 수 있으며, 충분한 안내가 없으면 개념을 잘못 일반화할 위험이 있다."}],"questions":[{"id":"edu-074-q1","prompt":"발견학습에서 교사가 수행할 지원 활동 두 가지를 서술하시오.","answer":"① 탐구에 적합한 문제와 다양한 자료를 제공한다. ② 학생의 탐색 과정에 질문·피드백·필요한 도움을 제공하여 개념의 발견과 검증을 돕는다.","keywords":["탐구 문제·자료 제공","질문·피드백·도움 제공"],"kind":"서술"},{"id":"edu-074-q2","prompt":"발견학습의 장점 한 가지와 유의점 한 가지를 쓰시오.","answer":"장점은 학습자가 자료를 탐색하면서 자기주도적 사고와 개념 이해를 발전시킬 기회가 있다는 점이다. 유의점은 시간·준비 부담이 클 수 있으므로 학생의 수준에 적합한 안내와 피드백을 제공해야 한다는 점이다.","keywords":["장점: 탐구·자기주도적 이해","유의점: 수준에 맞는 안내·시간 부담"],"kind":"비교"}],"source":{"document":"교육학_261019_163033.pdf","page":11,"status":"필기 11쪽 표제·주요 내용 확인 + 학습용 재서술","note":"원본 필기의 표제어와 핵심 메모를 참고하여 학습 문장·연습문항을 새로 작성했습니다. 공식 기출 발문이나 채점기준이 아닙니다."}},{"id":"edu-075","area":"교육방법","title":"플립러닝(거꾸로 수업)","page":11,"summary":"학습 전 개별 학습과 수업 시간의 적용·상호작용을 연결하는 수업 운영 방식이다.","sections":[{"heading":"학습 단계","text":"수업 전에 동영상 등으로 기본 개념을 학습하고, 교실 수업에서는 질문·토론·문제해결·협력활동 등 능동적 활동에 시간을 사용한다."},{"heading":"교사의 역할","text":"사전 자료를 준비하고 학습 여부를 점검하며, 대면 수업에서 학습자 수준에 따른 피드백과 상호작용을 촉진한다."},{"heading":"유의점","text":"사전 학습 접근성과 참여 격차를 고려해야 하며, 단지 동영상을 숙제로 내는 것만으로 수업 중의 심화 학습이 보장되지는 않는다."}],"questions":[{"id":"edu-075-q1","prompt":"플립러닝에서 수업 전 활동과 교실 수업 중 활동을 각각 서술하시오.","answer":"수업 전에는 기본 개념을 동영상·읽기 자료 등으로 개별 학습한다. 교실에서는 질문, 토의, 문제해결 또는 협력활동을 통해 배운 내용을 적용·심화한다.","keywords":["수업 전: 기본 개념 개별 학습","수업 중: 적용·토의·문제해결"],"kind":"비교"},{"id":"edu-075-q2","prompt":"플립러닝을 운영할 때 교사가 점검할 요소 두 가지를 설명하시오.","answer":"① 학생들이 사전 학습 자료에 접근하고 실제로 학습했는지 확인한다. ② 수업 시간에 학생들의 이해 수준을 확인하고 피드백과 상호작용 중심의 활동을 설계한다.","keywords":["사전 학습 접근·참여 확인","교실 피드백·상호작용 설계"],"kind":"서술"}],"source":{"document":"교육학_261019_163033.pdf","page":11,"status":"필기 11쪽 표제·주요 내용 확인 + 학습용 재서술","note":"원본 필기의 표제어와 핵심 메모를 참고하여 학습 문장·연습문항을 새로 작성했습니다. 공식 기출 발문이나 채점기준이 아닙니다."}},{"id":"edu-076","area":"교육방법","title":"문제해결학습","page":12,"summary":"학습자가 문제를 인식하고 해결 방안을 탐색·검증하는 사고 과정을 중심으로 하는 학습이다.","sections":[{"heading":"필기의 대표적 흐름","text":"문제 인식 → 구상 → 해결 설정 → 명료화 → 반성적 사고 → 탐색의 흐름이 메모되어 있다. 수업 상황에 따라 실제 단계가 왕복하거나 재구성될 수 있으므로 기계적인 고정 순서로만 이해하지 않는다."},{"heading":"핵심 기능","text":"정보를 수집하고 가설·대안을 비교하며 근거를 검토하는 문제해결 사고 능력을 기르는 데 초점을 둔다."},{"heading":"PBL과 구별","text":"문제해결학습은 문제를 해결하는 인지적 과정을 중심으로 설명할 수 있다. 문제중심학습(PBL)은 비구조화된 실제적 문제를 출발점으로 자기주도학습과 협력적 탐구를 조직하는 수업 접근이다. 두 접근은 일부 활동을 공유할 수 있다."}],"questions":[{"id":"edu-076-q1","prompt":"문제해결학습에서 학습자가 거치는 대표적인 사고 활동 세 가지를 제시하시오.","answer":"예를 들어 ① 문제를 인식하고 명료화한다. ② 해결 방안을 구상하고 탐색한다. ③ 해결의 적절성을 검토하고 반성한다.","keywords":["문제 인식·명료화","해결 방안 구상·탐색","검토·반성"],"kind":"서술"},{"id":"edu-076-q2","prompt":"문제해결학습의 목표를 단순한 정답 찾기와 구별하여 설명하시오.","answer":"문제해결학습은 정답 도출뿐 아니라 문제를 파악하고 근거를 찾아 대안을 비교·검토하며 해결 과정을 반성하는 사고 능력을 기르는 것을 중시한다.","keywords":["문제 파악","대안·근거 검토","과정 반성"],"kind":"설명"}],"source":{"document":"교육학_261019_163033.pdf","page":12,"status":"필기 12쪽 표제·주요 내용 확인 + 학습용 재서술","note":"원본 필기의 표제어와 핵심 메모를 참고하여 학습 문장·연습문항을 새로 작성했습니다. 공식 기출 발문이나 채점기준이 아닙니다."}},{"id":"edu-077","area":"교육방법","title":"상황학습","page":12,"summary":"지식이 실제로 사용되는 사회적·문화적 맥락에서 참여와 활동을 통해 학습한다는 관점이다.","sections":[{"heading":"핵심 관점","text":"지식은 그것이 사용되는 맥락 및 활동과 분리해서 이해하기 어렵다. 실제적 과제와 참여 활동을 통해 배운 지식을 의미 있게 활용하도록 한다."},{"heading":"수업 적용","text":"학생이 실제에 가까운 문제 상황에 참여하고 타인과 협력하면서 해결 방안을 탐색하도록 조직할 수 있다."},{"heading":"정착수업과 구별","text":"정착수업은 영상 등의 이야기형 과제를 공통된 문제해결 맥락(앵커)으로 제시하는 교수설계 방식이다. 상황학습은 맥락 속 참여와 지식 형성이라는 보다 넓은 학습 관점을 가리킨다."}],"questions":[{"id":"edu-077-q1","prompt":"상황학습에서 학습의 맥락이 중요한 이유를 설명하시오.","answer":"학습한 지식의 의미와 사용 방식이 실제 활동 및 사회적·문화적 맥락과 밀접하기 때문에, 지식을 그 맥락 속에서 활용하고 참여하는 경험이 중요하다.","keywords":["지식 사용 맥락","실제 활동·참여"],"kind":"설명"},{"id":"edu-077-q2","prompt":"상황학습과 정착수업의 초점 차이를 한 가지 설명하시오.","answer":"상황학습은 지식을 사용되는 실제적·사회적 맥락 속에서 참여하며 배우는 원리를 강조한다. 정착수업은 영상 등으로 제시된 이야기형 과제를 문제해결의 공통 맥락으로 활용하는 수업 설계를 강조한다.","keywords":["상황학습의 실제적·사회적 맥락 참여와 정착수업의 공통 앵커 문제 비교"],"kind":"비교"}],"source":{"document":"교육학_261019_163033.pdf","page":12,"status":"필기 12쪽 표제·주요 내용 확인 + 학습용 재서술","note":"원본 필기의 표제어와 핵심 메모를 참고하여 학습 문장·연습문항을 새로 작성했습니다. 공식 기출 발문이나 채점기준이 아닙니다."}},{"id":"edu-078","area":"교육방법","title":"자원기반학습","page":12,"summary":"학습자가 과제 해결에 필요한 다양한 학습 자원을 탐색·선정·활용하도록 하는 학습 방식이다.","sections":[{"heading":"학습 자원","text":"인적 자원(교사·동료 등), 물적·정보 자원(교재·인터넷·도서관·사전 등)을 과제와 목적에 따라 활용한다."},{"heading":"학습자의 역할","text":"학습자는 자료를 찾는 데 그치지 않고 적합성·신뢰성을 판단하여 정보와 도움을 학습 과제에 맞게 사용한다."},{"heading":"교사의 역할","text":"과제와 탐색 방향을 명확히 하고, 자원 접근성을 지원하며 정보 선택·활용 과정을 지도한다."}],"questions":[{"id":"edu-078-q1","prompt":"자원기반학습에서 활용할 수 있는 인적 자원과 정보 자원을 각각 한 가지 제시하시오.","answer":"인적 자원의 예로 교사 또는 동료 학습자가 있고, 정보 자원의 예로 도서관 자료 또는 인터넷 자료가 있다.","keywords":["인적 자원 한 가지","정보 자원 한 가지"],"kind":"개념"},{"id":"edu-078-q2","prompt":"자원기반학습에서 단순 검색을 넘어 학생에게 요구되는 학습 활동을 설명하시오.","answer":"학습자는 다양한 자료를 탐색한 뒤 과제와의 관련성 및 자료의 신뢰성을 판단하고, 적절한 자원을 선택·종합하여 과제를 해결해야 한다.","keywords":["탐색","관련성·신뢰성 판단","선택·활용"],"kind":"설명"}],"source":{"document":"교육학_261019_163033.pdf","page":12,"status":"필기 12쪽 표제·주요 내용 확인 + 학습용 재서술","note":"원본 필기의 표제어와 핵심 메모를 참고하여 학습 문장·연습문항을 새로 작성했습니다. 공식 기출 발문이나 채점기준이 아닙니다."}},{"id":"edu-079","area":"교육방법","title":"가네의 9가지 수업사태","page":13,"summary":"주의집중부터 파지·전이 촉진까지 수업 활동을 조직하는 대표적 교수사태를 이해한다.","sections":[{"heading":"아홉 가지 교수사태","text":"① 주의집중 유도 ② 학습목표 제시 ③ 선수학습 회상 ④ 자극자료 제시 ⑤ 학습안내 제공 ⑥ 수행 유도 ⑦ 피드백 제공 ⑧ 수행평가 ⑨ 파지 및 전이 촉진."},{"heading":"수업의 흐름","text":"학습 준비와 정보 제시, 수행과 피드백, 평가 및 전이 지원을 연결한다. 실제 수업에서 모든 활동을 같은 길이·형식으로 운영해야 한다는 뜻은 아니다."},{"heading":"유사 개념 구분","text":"수행 유도는 학습자가 학습 내용을 실제로 실행해 보도록 하는 활동이고, 피드백은 수행의 적절성을 알려 교정·보완하도록 돕는 활동이다."}],"questions":[{"id":"edu-079-q1","prompt":"가네의 9가지 수업사태 중 수행 유도 이후의 세 단계를 순서대로 쓰시오.","answer":"⑦ 피드백 제공 → ⑧ 수행평가 → ⑨ 파지 및 전이 촉진.","keywords":["피드백 제공","수행평가","파지·전이 촉진"],"kind":"절차"},{"id":"edu-079-q2","prompt":"가네의 교수사태에서 선수학습 회상과 학습안내 제공의 기능을 각각 설명하시오.","answer":"선수학습 회상은 이전에 배운 관련 지식·기능을 떠올려 새 학습과 연결하도록 하는 활동이다. 학습안내 제공은 이해와 수행에 도움이 되는 단서·설명·예시 등을 제공하는 활동이다.","keywords":["선수학습: 관련 지식 회상·연결","학습안내: 단서·예시 제공"],"kind":"비교"}],"source":{"document":"교육학_261019_163033.pdf","page":13,"status":"필기 13쪽 표제·주요 내용 확인 + 학습용 재서술","note":"원본 필기의 표제어와 핵심 메모를 참고하여 학습 문장·연습문항을 새로 작성했습니다. 공식 기출 발문이나 채점기준이 아닙니다."}},{"id":"edu-080","area":"학습이론","title":"통찰학습과 아하 경험","page":2,"summary":"문제 상황의 관계를 새롭게 파악하면서 해결이 갑자기 떠오르는 통찰학습을 이해한다.","sections":[{"heading":"필기 내용","text":"2쪽의 학습이론 항목에 통찰학습을 ‘아하’ 현상, 비약적 사고의 과정으로 메모하였다."},{"heading":"핵심 개념","text":"통찰학습은 문제를 이루는 요소의 관계를 재구성하거나 전체 구조를 이해하는 과정에서 해결 방법을 발견하는 학습이다. 단순 시행착오 횟수의 누적만으로 설명하지 않는다."},{"heading":"수업 적용","text":"기계적인 정답 반복보다 문제의 요소·관계·대안을 살펴볼 기회를 제공한다. 통찰이 반드시 한 번에 일어나거나 모든 학습에 적용된다고 단정하지 않는다."}],"questions":[{"id":"edu-080-q1","prompt":"통찰학습에서 아하 경험의 의미를 설명하시오.","answer":"문제를 이루는 요소 사이의 관계나 전체 구조를 새롭게 이해하면서 해결 방법이 갑자기 떠오르는 경험을 뜻한다.","keywords":["문제 요소의 관계 재구성","해결 방법의 갑작스러운 이해"],"kind":"개념"},{"id":"edu-080-q2","prompt":"통찰학습을 촉진하기 위한 교사의 지원 방안을 두 가지 제시하시오.","answer":"① 학습자가 문제 상황의 요소와 관계를 다양한 관점에서 탐색하도록 한다. ② 단일한 풀이를 즉시 제시하기보다 기존 접근을 재구성할 단서·질문을 제공한다.","keywords":["다양한 관점·관계 탐색","재구성할 단서·질문 제공"],"kind":"적용"}],"source":{"document":"교육학_261019_163033.pdf","page":2,"status":"필기 2쪽 관련 항목 직접 확인·학습용 재서술","note":"원본 필기는 통찰학습의 명칭과 아하 현상을 간략히 기록하므로, 상세한 개념과 수업 적용은 학습용 설명으로 보완했습니다. 원문 직인용이나 공식 임용 채점기준이 아닙니다."}},{"id":"edu-081","area":"학습동기","title":"와이너의 귀인이론","page":4,"summary":"학생이 성공·실패 원인을 어떻게 해석하는지에 따라 후속 기대·정서·동기가 달라질 수 있음을 이해한다.","sections":[{"heading":"귀인의 세 차원","text":"원인의 소재(내적·외적), 안정성(안정·불안정), 통제 가능성(통제 가능·불가능)으로 성공·실패 원인에 대한 지각을 분석한다."},{"heading":"원인 해석의 대표적 사례","text":"능력은 대체로 내적·안정적·통제 곤란, 노력은 내적·불안정적·통제 가능, 과제 난이도는 외적·안정적·통제 곤란, 운은 외적·불안정적·통제 곤란의 전형적인 예로 제시된다. 이는 학습자의 지각에 따라 달라질 수 있는 예시다."},{"heading":"교사의 피드백","text":"실패를 바꿀 수 없는 능력 부족으로만 해석하도록 만들기보다, 조정 가능한 전략·노력과 구체적인 개선 행동에 주목하도록 돕는다. 단순히 노력을 강조하기보다 효과적인 전략도 제시해야 한다."}],"questions":[{"id":"edu-081-q1","prompt":"귀인이론에서 성공과 실패 원인을 해석하는 세 차원을 쓰시오.","answer":"원인의 소재(내적·외적), 안정성(안정적·불안정적), 통제 가능성(통제 가능·불가능)이다.","keywords":["원인의 소재","안정성","통제 가능성"],"kind":"개념"},{"id":"edu-081-q2","prompt":"시험에 실패한 학생이 “나는 원래 능력이 없어서 절대 못 한다”고 말할 때 교사의 피드백 방향을 서술하시오.","answer":"능력을 바꿀 수 없는 실패 원인으로 단정하지 않도록 돕고, 학습 전략·준비 방식처럼 조정할 수 있는 구체적 행동을 함께 찾아 다음 시도를 계획하도록 지원한다.","keywords":["고정적인 실패 원인 단정 완화","조정 가능한 전략·행동 제시"],"kind":"적용"}],"source":{"document":"교육학_261019_163033.pdf","page":4,"status":"필기 4쪽 관련 항목 직접 확인·학습용 재서술","note":"4쪽의 원인 소재·안정성·통제 가능성 표를 확인했고, 사례는 대표적인 이론적 분류로 학습용 재서술했습니다. 원문 직인용이나 공식 임용 채점기준이 아닙니다."}},{"id":"edu-082","area":"학습동기","title":"피그말리온 효과와 교사의 기대","page":4,"summary":"교사의 기대가 상호작용과 학습 기회를 통해 학생의 수행에 영향을 줄 수 있음을 이해한다.","sections":[{"heading":"핵심 개념","text":"교사의 기대가 학생에게 제공하는 기회, 피드백, 상호작용에 반영되고 결과적으로 학생의 학습 경험이나 수행에 영향을 줄 수 있는 현상이다."},{"heading":"수업 시사점","text":"학생별로 학습 기회·질문·피드백을 불균형하게 제공하지 않는지 점검하고, 학생의 성장 가능성을 열어 둔 기대와 구체적인 지원을 연결한다."},{"heading":"해석상의 주의","text":"교사의 긍정적 기대만으로 모든 학생의 성취가 자동으로 높아진다는 뜻은 아니다. 학습 조건과 실제 지원 행동 등을 함께 고려해야 한다."}],"questions":[{"id":"edu-082-q1","prompt":"피그말리온 효과를 교사의 기대와 상호작용의 관계로 설명하시오.","answer":"교사의 기대가 학생에게 주는 학습 기회·질문·피드백 등의 상호작용에 반영되면서 학생의 학습 경험과 수행에 영향을 줄 수 있다는 것이다.","keywords":["교사의 기대","상호작용·지원의 차이","학생 수행에 미치는 영향"],"kind":"설명"},{"id":"edu-082-q2","prompt":"교사가 피그말리온 효과를 고려할 때 점검할 수업 행동 두 가지를 쓰시오.","answer":"① 학생에게 질문과 참여 기회를 공정하게 제공하는지 점검한다. ② 개인의 성장 가능성을 고려해 구체적이고 도전 가능한 과제와 피드백을 제공한다.","keywords":["참여 기회의 공정성","성장 가능성에 대한 구체적 지원"],"kind":"적용"}],"source":{"document":"교육학_261019_163033.pdf","page":4,"status":"필기 4쪽 관련 항목 직접 확인·학습용 재서술","note":"4쪽에 용어와 기대가 행동·성취에 영향을 미칠 수 있다는 취지의 메모를 확인했습니다. 인과관계의 보편성을 단정하지 않도록 보완했습니다. 원문 직인용이나 공식 임용 채점기준이 아닙니다."}},{"id":"edu-083","area":"교육심리","title":"창의적 사고 기법","page":5,"summary":"원본 필기에 제시된 브레인스토밍·PMI·시네틱스를 구별하고 수업에 적용한다.","sections":[{"heading":"브레인스토밍","text":"아이디어를 생성하는 초기 단계에서 비판을 유보하고 자유롭게 다양한 아이디어를 제안하도록 하는 기법이다. 아이디어의 평가와 선택은 이후 별도로 할 수 있다."},{"heading":"PMI 기법","text":"어떤 제안이나 대상의 장점(Plus), 단점(Minus), 흥미로운 점(Interesting)을 나누어 생각하며 관점을 확장한다."},{"heading":"시네틱스","text":"비유·유추를 이용해 익숙한 문제를 낯설게 보거나 낯선 것을 친숙하게 연결하여 새로운 아이디어를 탐색하는 기법이다."},{"heading":"기존 창의성 요소와의 차이","text":"유창성·융통성·독창성·정교성은 창의적 사고의 특성을 구분한 것이고, 브레인스토밍·PMI·시네틱스는 사고를 촉진하기 위한 활동 기법이다."}],"questions":[{"id":"edu-083-q1","prompt":"브레인스토밍과 PMI 기법의 활동 방법을 각각 설명하시오.","answer":"브레인스토밍은 초기 비판을 유보하고 자유롭게 다양한 아이디어를 생성하는 기법이다. PMI는 대상의 장점(Plus), 단점(Minus), 흥미로운 점(Interesting)을 구분해 사고하는 기법이다.","keywords":["브레인스토밍: 비판 유보·아이디어 생성","PMI: 장점·단점·흥미로운 점"],"kind":"비교"},{"id":"edu-083-q2","prompt":"시네틱스에서 새로운 아이디어를 생성하기 위해 활용하는 사고 방법을 쓰시오.","answer":"비유와 유추를 활용해 문제를 새로운 관점에서 바라보고 서로 다른 대상이나 상황 사이의 연결을 탐색한다.","keywords":["비유·유추","새 관점·연결 탐색"],"kind":"개념"}],"source":{"document":"교육학_261019_163033.pdf","page":5,"status":"필기 5쪽 관련 항목 직접 확인·학습용 재서술","note":"5쪽의 브레인스토밍·PMI·시네틱스 표제를 확인했습니다. 활동의 상세 설명은 학습용으로 재서술했습니다. 원문 직인용이나 공식 임용 채점기준이 아닙니다."}}]};
